/**
 * Scroll reveals for dropbox.com.
 *
 * The page hides three groups of content behind a stylesheet class and adds a
 * "visible" class with its own JS during scroll. Codegen captures the DOM
 * pre-scroll, so without this module those blocks ship frozen at `opacity: 0`
 * (plus blur/scale) forever — no error, just blank space under a heading.
 *
 * Pairs come from `scrape/analysis/scroll-reveals.json`, which diffs class
 * tokens pre/post scroll and flags the ones whose base rule gates visibility.
 *
 * TWO NON-OBVIOUS DETAILS
 * -----------------------
 * 1. CLIPPED CONTAINERS. The quote cards live in a horizontally scrollable rail
 *    (`overflow-x: scroll`) that is far wider than the viewport, so the third
 *    card sits outside the clip window. IntersectionObserver computes
 *    intersection THROUGH that clip while `rootMargin` inflates only the root
 *    rect — so a wide margin does not help, and that card would stay invisible
 *    at every viewport. Hence `groupSelector`: observe the rail and reveal all
 *    of its members at once.
 * 2. `threshold: 0`. A rail ~2.4k px wide peaks near a 0.15 intersection ratio
 *    on a 375px phone, so any fractional threshold could never fire.
 *
 * No JS stagger: the capture already ships inline `--dwg-iteration-index` and
 * the site's CSS turns it into `animation-delay`.
 */
import { $all, prefersReducedMotion, type Teardown } from './runtime';

export interface RevealPair {
  /** Selector for elements the stylesheet hides. */
  base: string;
  /** Class the site's own JS adds to reveal them. */
  visible: string;
  /**
   * Optional clipping/grouping ancestor to observe instead of each element.
   * Required whenever members can sit outside an `overflow` container.
   */
  groupSelector?: string;
}

/**
 * Capture-bound: the hashed CSS-module names rotate whenever Dropbox rebuilds.
 * `tests/dropbox.test.ts` asserts every pair still matches the generated
 * markup, so a rotation fails the suite instead of silently blanking the page.
 */
export const DROPBOX_REVEAL_PAIRS: readonly RevealPair[] = [
  // 9 carriers: the "Do more" / "Everything you need" card grids.
  {
    base: '.dwg-multi-block-card-entry-animation',
    visible: 'dwg-multi-block-card-entry-animation--is-visible',
  },
  // 3 carriers: security quote cards inside the clipped, draggable rail.
  {
    base: '._card_1b963_1._cardEntryAnimation_1b963_1',
    visible: '_cardShow_1b963_8',
    groupSelector: '._scrollArea_bb0ya_5',
  },
  // 1 carrier: the share-UI media stack (base rule translateY(300px)).
  {
    base: '._mediaContainer_thadj_29',
    visible: '_mediaContainerVisible_thadj_62',
  },
];

export interface DropboxRevealOptions {
  pairs?: readonly RevealPair[];
  /**
   * Belt-and-braces for the rails. Does NOT fix clipping (see the header note)
   * but does reveal a group slightly before it scrolls in.
   */
  rootMargin?: string;
}

export function createDropboxReveals(options: DropboxRevealOptions = {}) {
  const { pairs = DROPBOX_REVEAL_PAIRS, rootMargin = '0px 200% 0px 200%' } = options;

  return function initDropboxReveals(root: ParentNode = document): Teardown | void {
    /** trigger element -> the targets revealed when it intersects. */
    const buckets = new Map<Element, Array<{ el: HTMLElement; visible: string }>>();

    for (const pair of pairs) {
      for (const el of $all(pair.base, root)) {
        // `?? el` is the drift fallback: if the rail's hashed class has
        // rotated, observe the card itself rather than reveal nothing.
        const trigger = (pair.groupSelector ? el.closest(pair.groupSelector) : null) ?? el;
        const bucket = buckets.get(trigger);
        if (bucket) bucket.push({ el, visible: pair.visible });
        else buckets.set(trigger, [{ el, visible: pair.visible }]);
      }
    }

    if (buckets.size === 0) return;

    const revealAll = (trigger: Element) => {
      for (const { el, visible } of buckets.get(trigger) ?? []) el.classList.add(visible);
    };

    // The site ships `@media (prefers-reduced-motion: reduce)` rules that reset
    // these blocks to visible, so reveal everything at once to match.
    if (prefersReducedMotion() || typeof IntersectionObserver === 'undefined') {
      for (const trigger of buckets.keys()) revealAll(trigger);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          revealAll(entry.target);
          // One-shot: index.scrolled.html still carries these classes after
          // the capture scrolled back to y=0, so the site never re-hides them.
          observer.unobserve(entry.target);
        }
      },
      { threshold: 0, rootMargin },
    );

    for (const trigger of buckets.keys()) observer.observe(trigger);

    return () => observer.disconnect();
  };
}

export const initDropboxReveals = createDropboxReveals();

/**
 * dropbox.com navigation: desktop dropdown panels + the mobile burger menu.
 *
 * WHY THIS IS HAND-WRITTEN RATHER THAN THE GENERIC `navToggle`/`navDropdown`
 * -------------------------------------------------------------------------
 * The generic modules DO match these elements (`[class*="hamburger"]`,
 * `[class*="nav-menu"]`) but apply their own `is-open` / `w--open` classes,
 * which this site's CSS knows nothing about — so they would fight this module
 * while producing no visible effect. They are deliberately unregistered.
 *
 * TWO CSS VARIABLES ARE RUNTIME-AUTHORED AND IN NO CAPTURED STYLESHEET
 * --------------------------------------------------------------------
 * The open-state rules read their height from variables the site's own JS
 * writes inline. Grepping all 122 captured sheets finds no definition for
 * either, which is evidence they were runtime-authored, not evidence of a
 * broken capture. Leave them unset and a dropdown "opens" to zero height:
 *
 *   .dwg-nav-item__dropdown--open            { max-height: var(--dwg-nav-item__dropdown-max-height) }   // < 1280px
 *   .dwg-nav-item--nav-redesign__dropdown
 *     .dwg-nav-item__dropdown--open          { max-height: var(--dwg-nav-current-dropdown-height) }     // >= 1280px
 *
 * Both are set here from the panel's own `scrollHeight` (which reports full
 * content height despite `max-height: 0; overflow: hidden`).
 *
 * `.dwg-nav__dropdown-background` is the white sheet behind an open desktop
 * panel — the panel itself is `desktop:dwg-bg-color--transparent`, so its
 * height has to be driven too or the dropdown reads as floating text.
 */
import { $all, type Teardown } from './runtime';

const SEL = {
  navRoot: '.dwg-nav--universal',
  /** The 6 real dropdown triggers: 3 horizontal (desktop) + 3 vertical (mobile). */
  trigger: 'button[aria-haspopup="true"][aria-controls]',
  backdrop: '.dwg-nav__dropdown-background',
  overlay: '.dwg-nav__overlay',
  burger: '.dwg-nav__hamburger-button',
  mobileDropdown: '.dwg-nav-mobile-dropdown',
} as const;

const CLS = {
  panelOpen: 'dwg-nav-item__dropdown--open',
  buttonOpen: 'dwg-nav-item-button--dropdown-open',
  navDropdownOpened: 'dwg-nav--dropdown-opened',
  backdropOpen: 'dwg-nav__dropdown-background--open',
  overlayOpen: 'dwg-nav__overlay--open',
  burgerOpen: 'dwg-nav__hamburger-button--open',
  mobileOpen: 'dwg-nav-mobile-dropdown--open',
  bodyMobileOpen: 'body--dwg-nav-mobile-dropdown-open--universal',
} as const;

const VAR_PANEL_MAX_MOBILE = '--dwg-nav-item__dropdown-max-height';
const VAR_PANEL_MAX_DESKTOP = '--dwg-nav-current-dropdown-height';

export function initDropboxNav(root: ParentNode = document): Teardown | void {
  const navRoot = root.querySelector<HTMLElement>(SEL.navRoot);
  const triggers = $all<HTMLButtonElement>(SEL.trigger, root);
  const burger = root.querySelector<HTMLElement>(SEL.burger);
  const mobileDropdown = root.querySelector<HTMLElement>(SEL.mobileDropdown);
  const backdrop = root.querySelector<HTMLElement>(SEL.backdrop);
  const overlay = root.querySelector<HTMLElement>(SEL.overlay);

  if (!triggers.length && !(burger && mobileDropdown)) return;

  const panelOf = (trigger: Element): HTMLElement | null => {
    const id = trigger.getAttribute('aria-controls');
    return id ? document.getElementById(id) : null;
  };

  const closeDropdowns = () => {
    for (const trigger of triggers) {
      trigger.classList.remove(CLS.buttonOpen);
      trigger.setAttribute('aria-expanded', 'false');
      const panel = panelOf(trigger);
      if (!panel) continue;
      panel.classList.remove(CLS.panelOpen);
      panel.style.removeProperty(VAR_PANEL_MAX_MOBILE);
      panel.style.removeProperty(VAR_PANEL_MAX_DESKTOP);
    }
    navRoot?.classList.remove(CLS.navDropdownOpened);
    if (backdrop) {
      backdrop.classList.remove(CLS.backdropOpen);
      backdrop.style.height = '0px';
    }
  };

  const openDropdown = (trigger: HTMLElement) => {
    const panel = panelOf(trigger);
    if (!panel) return;

    closeDropdowns();

    // Measured before the open class lands: `max-height` never clips
    // scrollHeight, so this is the panel's full content height either way.
    const height = panel.scrollHeight;
    panel.style.setProperty(VAR_PANEL_MAX_MOBILE, `${height}px`);
    panel.style.setProperty(VAR_PANEL_MAX_DESKTOP, `${height}px`);
    panel.classList.add(CLS.panelOpen);

    trigger.classList.add(CLS.buttonOpen);
    trigger.setAttribute('aria-expanded', 'true');
    // Gates the per-item opacity/translate stagger on the dropdown's links.
    navRoot?.classList.add(CLS.navDropdownOpened);

    if (backdrop) {
      backdrop.style.height = `${height}px`;
      backdrop.classList.add(CLS.backdropOpen);
    }
  };

  const isDropdownOpen = (trigger: Element) =>
    trigger.getAttribute('aria-expanded') === 'true';

  const setMobileOpen = (open: boolean) => {
    if (!burger || !mobileDropdown) return;
    mobileDropdown.classList.toggle(CLS.mobileOpen, open);
    burger.classList.toggle(CLS.burgerOpen, open);
    burger.setAttribute('aria-expanded', String(open));
    overlay?.classList.toggle(CLS.overlayOpen, open);
    // The site's own rule: body overflow is locked while the sheet is open.
    document.body.classList.toggle(CLS.bodyMobileOpen, open);
    if (!open) closeDropdowns();
  };

  const isMobileOpen = () => !!mobileDropdown?.classList.contains(CLS.mobileOpen);

  const cleanups: Array<() => void> = [];

  for (const trigger of triggers) {
    const onClick = (event: Event) => {
      // These are <button>s so there is no href to suppress, but the original
      // handler stopped propagation reaching the document-level close below.
      event.preventDefault();
      event.stopPropagation();
      if (isDropdownOpen(trigger)) closeDropdowns();
      else openDropdown(trigger);
    };
    trigger.setAttribute('aria-expanded', 'false');
    trigger.addEventListener('click', onClick);
    cleanups.push(() => trigger.removeEventListener('click', onClick));
  }

  if (burger && mobileDropdown) {
    const onBurger = (event: Event) => {
      event.preventDefault();
      event.stopPropagation();
      setMobileOpen(!isMobileOpen());
    };
    burger.setAttribute('aria-expanded', 'false');
    burger.addEventListener('click', onBurger);
    cleanups.push(() => burger.removeEventListener('click', onBurger));
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== 'Escape') return;
    closeDropdowns();
    setMobileOpen(false);
  };

  const onDocumentClick = (event: MouseEvent) => {
    const target = event.target as Node | null;
    if (target && navRoot?.contains(target)) return;
    closeDropdowns();
    setMobileOpen(false);
  };

  document.addEventListener('keydown', onKeyDown);
  document.addEventListener('click', onDocumentClick);
  cleanups.push(() => {
    document.removeEventListener('keydown', onKeyDown);
    document.removeEventListener('click', onDocumentClick);
  });

  return () => {
    for (const cleanup of cleanups) cleanup();
    closeDropdowns();
    setMobileOpen(false);
    document.body.classList.remove(CLS.bodyMobileOpen);
  };
}

/**
 * Autoplay for the 4 looping product videos (hero + find/organize/share).
 *
 * THE TRAP: a JSX `muted` attribute is NOT enough.
 * ------------------------------------------------
 * Browsers only permit unattended autoplay on a video that is *muted*, and
 * they read that from the DOM **property**, not the attribute React rendered.
 * Shipping `<video autoPlay muted>` alone therefore yields a silently paused
 * first frame — no console error, and the viewport audit's broken-image style
 * checks can't see it either. So `muted` / `defaultMuted` / `playsInline` are
 * assigned as properties here, then `.play()` is called explicitly.
 *
 * The retry on `canplay`/`loadeddata` covers the case where the element is not
 * yet decodable when the effect first runs (these are multi-MB `.webm` files).
 *
 * Scoped to `video[autoplay]` on purpose: a video the original page did not
 * autoplay must stay paused.
 */
import { $all, type Teardown } from './runtime';

export function initDropboxVideos(root: ParentNode = document): Teardown | void {
  const videos = $all<HTMLVideoElement>('video[autoplay]', root);
  if (!videos.length) return;

  const cleanups: Array<() => void> = [];

  for (const video of videos) {
    // Properties, not attributes — see the header note.
    video.muted = true;
    video.defaultMuted = true;
    video.playsInline = true;

    const attemptPlay = () => {
      try {
        const played = video.play() as Promise<void> | undefined;
        // Autoplay rejection is expected and harmless; swallow it rather than
        // letting an unhandled rejection surface as a console error.
        if (played && typeof played.catch === 'function') played.catch(() => {});
      } catch {
        /* jsdom and locked-down policies both throw synchronously here */
      }
    };

    attemptPlay();
    video.addEventListener('canplay', attemptPlay);
    video.addEventListener('loadeddata', attemptPlay);

    cleanups.push(() => {
      video.removeEventListener('canplay', attemptPlay);
      video.removeEventListener('loadeddata', attemptPlay);
    });
  }

  return () => {
    for (const cleanup of cleanups) cleanup();
  };
}

/**
 * Types-only augmentation for Dropbox's `dwg-*` component attributes.
 *
 * WHY THIS EXISTS
 * ---------------
 * Dropbox's own design-system components render genuine, non-standard
 * attributes onto standard elements — `label` and `tag` on `<a>`:
 *
 *     <a class="dwg-button2 ..." label="Get started" tag="a" href="...">
 *
 * These are real upstream markup, live in the served DOM, not capture
 * artifacts, so stripping them would make the replica *less* faithful. But
 * React's `HTMLAttributes` has no such keys, so `tsc` rejects every one of
 * them (~50 × TS2322 on this page).
 *
 * Widening `HTMLAttributes` is the minimal, additive fix: it only adds these
 * two optional keys, so genuine typos in real attribute names are still
 * caught. The alternative — casting each generated element's props — would
 * silence real errors across the whole component tree.
 *
 * Same shape as the template's standing `css-custom-properties.d.ts` fix.
 */

declare module 'react' {
  interface HTMLAttributes<T> {
    /** `dwg-button2` / `dwg-nav-item` accessible label passthrough. */
    label?: string;
    /** Element the `dwg-*` component was asked to render as ("a", "button"). */
    tag?: string;
  }
}

export {};

'use client';

/**
 * Re-applies the behaviours the original page's JavaScript provided.
 *
 * Codegen captures the DOM *before* scroll and strips runtime-added classes,
 * so the markup starts in its pristine pre-animation state. Everything that
 * made dropbox.com feel alive is re-implemented here.
 *
 * EVERY GENERIC EFFECT WAS CENSUSED AGAINST THE GENERATED MARKUP.
 * Ten are deliberately NOT registered — eight because they match nothing, and
 * two because they match but are actively harmful. Recorded here so a future
 * run does not helpfully re-add them:
 *
 *   zero targets in app/generated/*.tsx (verified by grep):
 *     fadeIn      - no `.fade-in` / `[data-fade]` / `[data-animate]`; this
 *                   site gates reveals on hashed CSS-module classes instead,
 *                   which is what `dropboxReveals` handles.
 *     navDropdown - no `.w-dropdown` / `[data-dropdown]`.
 *     tabs        - no `.w-tab-link` / `[role="tab"]` / `[data-tab]`.
 *     accordion   - no `.accordion-item` / `.faq-item`.
 *     counters    - no `[data-counter]` / `[data-count-to]`.
 *     lazyImages  - no `img[data-src]` / `[data-bg]`. (`features.json` reports
 *                   77 "lazyImages" but those are native `loading="lazy"`,
 *                   which needs no JS.)
 *     forms       - no `<form>` anywhere on the page.
 *     navScroll   - the nav is CSS `position: sticky`; no scrolled-state class
 *                   exists in the captured CSS.
 *
 *   matches real elements but MUST NOT run:
 *     navToggle   - matches `.dwg-nav__hamburger-button` / `.dwg-nav-menu*`
 *                   but applies its own `is-open`/`nav-open` classes, which
 *                   this site's CSS does not define. It would fight
 *                   `dropboxNav` while producing no visible effect.
 *     marquee     - matches the logo ticker `._ticker_90hav_23`, which is
 *                   ALREADY CSS-animated (`@keyframes _keyframes-standard_90hav_1`,
 *                   translateX -30% -> -50%) over markup that ALREADY contains
 *                   duplicated content. Cloning a third copy desyncs the wrap.
 *
 * `smoothAnchors` IS registered: it matches exactly two real navigation
 * anchors (`#main-content`, `#manage-cookies`), neither of which is a widget
 * control, so it cannot cause the autoplay-driven scroll-hijack trap.
 */

import { useEffect } from 'react';
import { initEffects, type RegisteredEffect } from './lib/runtime';
import { initSmoothAnchors } from './lib/nav';
import { initDropboxReveals } from './lib/dropboxReveals';
import { initDropboxNav } from './lib/dropboxNav';
import { initDropboxVideos } from './lib/dropboxVideos';

const effects: RegisteredEffect[] = [
  // Re-applies the 3 visibility-gating classes from scroll-reveals.json.
  { name: 'dropboxReveals', init: initDropboxReveals },
  // 6 dropdown panels + the mobile burger sheet, incl. the two runtime-only
  // CSS height variables that exist in none of the captured stylesheets.
  { name: 'dropboxNav', init: initDropboxNav },
  // `muted` as a DOM property so the 4 looping .webm files may autoplay.
  { name: 'dropboxVideos', init: initDropboxVideos },
  // Generic, kept: 2 real in-page anchors.
  { name: 'smoothAnchors', init: initSmoothAnchors },
];

export default function ClientRuntime() {
  useEffect(() => {
    // Deferred one frame so the generated markup is committed and laid out
    // before any effect measures it (the nav reads panel scrollHeight).
    let teardown: (() => void) | undefined;
    const raf = requestAnimationFrame(() => {
      teardown = initEffects(effects);
    });
    return () => {
      cancelAnimationFrame(raf);
      teardown?.();
    };
  }, []);

  return null;
}

/**
 * Behavioural + drift tests for the dropbox.com-specific effect modules.
 *
 * Two kinds of test live here, and the second kind matters as much as the first:
 *
 *  1. BEHAVIOUR — the reveal/nav/video logic, driven through the jsdom
 *     IntersectionObserver mock in tests/setup.ts.
 *  2. DRIFT — the selectors these modules depend on are *capture-bound*.
 *     Dropbox's hashed CSS-module names (`_card_1b963_1`, `_scrollArea_bb0ya_5`,
 *     `_cardShow_1b963_8`) rotate whenever they rebuild, and a rotated hash
 *     would silently blank whole sections instead of erroring. So every pair is
 *     asserted against the *generated markup*, and the modules are asserted to
 *     be actually registered in ClientRuntime — a perfectly correct but
 *     unregistered effect is exactly how this ships broken.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { observedElementCount, observerOptionsFor, resetObservers, triggerIntersection } from './setup';
import {
  DROPBOX_REVEAL_PAIRS,
  createDropboxReveals,
  initDropboxReveals,
} from '../app/lib/dropboxReveals';
import { initDropboxNav } from '../app/lib/dropboxNav';
import { initDropboxVideos } from '../app/lib/dropboxVideos';

const root = resolve(__dirname, '..');
const generatedDir = join(root, 'app', 'generated');

beforeEach(() => {
  document.body.innerHTML = '';
  document.body.className = '';
  resetObservers();
});

/* ------------------------------------------------------------------ reveals */

/** The real shape: a clipped rail whose third card sits outside the window. */
const railMarkup = `
  <div class="_scrollArea_bb0ya_5 _grabbable_bb0ya_17" id="rail">
    <div class="_quoteCardsGrid_thadj_158">
      <div class="_card_1b963_1 _cardEntryAnimation_1b963_1" id="c0"></div>
      <div class="_card_1b963_1 _cardEntryAnimation_1b963_1" id="c1"></div>
      <div class="_card_1b963_1 _cardEntryAnimation_1b963_1" id="c2"></div>
    </div>
  </div>`;

describe('dropboxReveals', () => {
  it('reveals nothing before the trigger intersects', () => {
    document.body.innerHTML = railMarkup;
    initDropboxReveals(document);
    for (const id of ['c0', 'c1', 'c2']) {
      expect(document.getElementById(id)!.classList.contains('_cardShow_1b963_8')).toBe(false);
    }
  });

  it('reveals EVERY member of a clipped rail, including the off-window card', () => {
    // The bug this guards: IntersectionObserver intersection is clipped by an
    // overflow ancestor while rootMargin inflates only the root rect, so the
    // third card can never intersect on its own and stayed invisible at all 7
    // viewports. The container is the trigger precisely to avoid that.
    document.body.innerHTML = railMarkup;
    initDropboxReveals(document);

    triggerIntersection(document.getElementById('rail')!);

    for (const id of ['c0', 'c1', 'c2']) {
      expect(
        document.getElementById(id)!.classList.contains('_cardShow_1b963_8'),
        `card ${id} was not revealed`,
      ).toBe(true);
    }
  });

  it('observes the rail itself, not the individual cards', () => {
    document.body.innerHTML = railMarkup;
    initDropboxReveals(document);
    expect(observerOptionsFor(document.getElementById('rail')!).length).toBe(1);
    expect(observerOptionsFor(document.getElementById('c2')!).length).toBe(0);
  });

  it('observes at threshold 0, since a rail wider than the viewport never reaches a ratio', () => {
    // A ~2.4k px rail peaks near 0.15 on a 375px phone, so any fractional
    // threshold would never fire. This assertion pins that reasoning.
    document.body.innerHTML = railMarkup;
    initDropboxReveals(document);
    const [options] = observerOptionsFor(document.getElementById('rail')!);
    expect(options.thresholds).toEqual([0]);
  });

  it('falls back to per-card observation when the rail class has rotated', () => {
    // Drift insurance: if `_scrollArea_bb0ya_5` changes, reveal must degrade to
    // observing each card rather than silently revealing nothing.
    document.body.innerHTML = `
      <div class="_scrollArea_ROTATED">
        <div class="_card_1b963_1 _cardEntryAnimation_1b963_1" id="c0"></div>
      </div>`;
    initDropboxReveals(document);

    const card = document.getElementById('c0')!;
    expect(observerOptionsFor(card).length).toBe(1);
    triggerIntersection(card);
    expect(card.classList.contains('_cardShow_1b963_8')).toBe(true);
  });

  it('is one-shot: stops observing once revealed', () => {
    // index.scrolled.html still carries these classes after the capture
    // scrolled back to y=0, so the live reveal never re-hides.
    document.body.innerHTML = railMarkup;
    initDropboxReveals(document);
    expect(observedElementCount()).toBe(1);

    triggerIntersection(document.getElementById('rail')!);
    expect(observedElementCount()).toBe(0);
  });

  it('reveals the multi-block cards individually (no group ancestor)', () => {
    document.body.innerHTML = `
      <div class="dwg-multi-block-card-entry-animation" id="m0"></div>
      <div class="dwg-multi-block-card-entry-animation" id="m1"></div>`;
    initDropboxReveals(document);

    const m0 = document.getElementById('m0')!;
    triggerIntersection(m0);
    expect(m0.classList.contains('dwg-multi-block-card-entry-animation--is-visible')).toBe(true);
    // Independently observed, so the second stays hidden until it scrolls in.
    expect(
      document
        .getElementById('m1')!
        .classList.contains('dwg-multi-block-card-entry-animation--is-visible'),
    ).toBe(false);
  });

  it('reveals everything immediately under prefers-reduced-motion', () => {
    // The site ships @media (prefers-reduced-motion: reduce) rules that reset
    // these blocks to visible, so matching means revealing without observing.
    const original = window.matchMedia;
    window.matchMedia = ((query: string) => ({
      matches: true,
      media: query,
      onchange: null,
      addListener: () => {},
      removeListener: () => {},
      addEventListener: () => {},
      removeEventListener: () => {},
      dispatchEvent: () => false,
    })) as unknown as typeof window.matchMedia;

    try {
      document.body.innerHTML = railMarkup;
      initDropboxReveals(document);
      expect(document.getElementById('c2')!.classList.contains('_cardShow_1b963_8')).toBe(true);
      expect(observedElementCount()).toBe(0);
    } finally {
      window.matchMedia = original;
    }
  });

  it('no-ops without targets', () => {
    expect(() => initDropboxReveals(document)).not.toThrow();
    expect(initDropboxReveals(document)).toBeUndefined();
  });

  it('disconnects on teardown', () => {
    document.body.innerHTML = railMarkup;
    const teardown = createDropboxReveals()(document);
    expect(observedElementCount()).toBe(1);
    if (typeof teardown === 'function') teardown();
    expect(observedElementCount()).toBe(0);
  });
});

/* ---------------------------------------------------------------------- nav */

const navMarkup = `
  <div class="dwg-nav dwg-nav--sticky dwg-nav--universal" id="nav">
    <div class="dwg-nav__overlay" id="overlay"></div>
    <div class="dwg-nav__dropdown-background" id="backdrop" style="height:0px"></div>
    <button id="t0" class="dwg-nav-item-button" aria-haspopup="true"
            aria-controls="p0" aria-expanded="false">Products</button>
    <div class="dwg-nav-item__dropdown" id="p0" role="menu"></div>
    <button id="t1" class="dwg-nav-item-button" aria-haspopup="true"
            aria-controls="p1" aria-expanded="false">Solutions</button>
    <div class="dwg-nav-item__dropdown" id="p1" role="menu"></div>
    <button id="burger" class="dwg-nav__hamburger-button"></button>
    <div class="dwg-nav-mobile-dropdown" id="mobile"></div>
  </div>`;

/** jsdom has no layout, so panel height has to be stubbed to a real number. */
function stubScrollHeight(id: string, value: number) {
  Object.defineProperty(document.getElementById(id)!, 'scrollHeight', {
    value,
    configurable: true,
  });
}

describe('dropboxNav', () => {
  it('opens a dropdown and sets BOTH runtime-only height variables', () => {
    // Neither variable is defined in any of the 122 captured stylesheets — the
    // site writes them inline. Unset, an "open" dropdown has max-height 0.
    document.body.innerHTML = navMarkup;
    stubScrollHeight('p0', 240);
    initDropboxNav(document);

    document.getElementById('t0')!.click();

    const panel = document.getElementById('p0')!;
    expect(panel.classList.contains('dwg-nav-item__dropdown--open')).toBe(true);
    expect(panel.style.getPropertyValue('--dwg-nav-item__dropdown-max-height')).toBe('240px');
    expect(panel.style.getPropertyValue('--dwg-nav-current-dropdown-height')).toBe('240px');
    expect(document.getElementById('t0')!.getAttribute('aria-expanded')).toBe('true');
    expect(document.getElementById('nav')!.classList.contains('dwg-nav--dropdown-opened')).toBe(true);
  });

  it('drives the dropdown background, which is what gives a desktop panel its surface', () => {
    document.body.innerHTML = navMarkup;
    stubScrollHeight('p0', 300);
    initDropboxNav(document);

    document.getElementById('t0')!.click();
    const backdrop = document.getElementById('backdrop')!;
    expect(backdrop.classList.contains('dwg-nav__dropdown-background--open')).toBe(true);
    expect(backdrop.style.height).toBe('300px');
  });

  it('closes an open dropdown when its trigger is clicked again', () => {
    document.body.innerHTML = navMarkup;
    stubScrollHeight('p0', 240);
    initDropboxNav(document);

    const trigger = document.getElementById('t0')!;
    trigger.click();
    trigger.click();

    const panel = document.getElementById('p0')!;
    expect(panel.classList.contains('dwg-nav-item__dropdown--open')).toBe(false);
    expect(panel.style.getPropertyValue('--dwg-nav-current-dropdown-height')).toBe('');
    expect(trigger.getAttribute('aria-expanded')).toBe('false');
  });

  it('only ever has one dropdown open', () => {
    document.body.innerHTML = navMarkup;
    stubScrollHeight('p0', 240);
    stubScrollHeight('p1', 260);
    initDropboxNav(document);

    document.getElementById('t0')!.click();
    document.getElementById('t1')!.click();

    expect(document.getElementById('p0')!.classList.contains('dwg-nav-item__dropdown--open')).toBe(false);
    expect(document.getElementById('p1')!.classList.contains('dwg-nav-item__dropdown--open')).toBe(true);
  });

  it('closes on Escape and on a click outside the nav', () => {
    document.body.innerHTML = `${navMarkup}<main id="outside">content</main>`;
    stubScrollHeight('p0', 240);
    initDropboxNav(document);

    document.getElementById('t0')!.click();
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }));
    expect(document.getElementById('p0')!.classList.contains('dwg-nav-item__dropdown--open')).toBe(false);

    document.getElementById('t0')!.click();
    document.getElementById('outside')!.click();
    expect(document.getElementById('p0')!.classList.contains('dwg-nav-item__dropdown--open')).toBe(false);
  });

  it('toggles the mobile sheet, the burger glyph and the body scroll lock', () => {
    document.body.innerHTML = navMarkup;
    initDropboxNav(document);

    const burger = document.getElementById('burger')!;
    burger.click();

    expect(document.getElementById('mobile')!.classList.contains('dwg-nav-mobile-dropdown--open')).toBe(true);
    expect(burger.classList.contains('dwg-nav__hamburger-button--open')).toBe(true);
    expect(burger.getAttribute('aria-expanded')).toBe('true');
    expect(document.getElementById('overlay')!.classList.contains('dwg-nav__overlay--open')).toBe(true);
    expect(document.body.classList.contains('body--dwg-nav-mobile-dropdown-open--universal')).toBe(true);

    burger.click();
    expect(document.getElementById('mobile')!.classList.contains('dwg-nav-mobile-dropdown--open')).toBe(false);
    expect(document.body.classList.contains('body--dwg-nav-mobile-dropdown-open--universal')).toBe(false);
  });

  it('releases the body scroll lock on teardown', () => {
    document.body.innerHTML = navMarkup;
    const teardown = initDropboxNav(document);
    document.getElementById('burger')!.click();
    expect(document.body.classList.contains('body--dwg-nav-mobile-dropdown-open--universal')).toBe(true);

    if (typeof teardown === 'function') teardown();
    expect(document.body.classList.contains('body--dwg-nav-mobile-dropdown-open--universal')).toBe(false);
  });

  it('no-ops without a nav', () => {
    expect(initDropboxNav(document)).toBeUndefined();
  });
});

/* ------------------------------------------------------------------- videos */

describe('dropboxVideos', () => {
  it('sets muted/playsInline as DOM PROPERTIES and calls play', () => {
    // A JSX `muted` attribute alone does not permit autoplay: the browser
    // reads the property. This is the whole reason the module exists.
    const play = vi.fn(() => Promise.resolve());
    (HTMLMediaElement.prototype as unknown as { play: () => Promise<void> }).play = play;

    document.body.innerHTML = `
      <video id="v" autoplay loop muted playsinline>
        <source src="/assets/video/hero.webm" type="video/webm; codecs=vp9" />
      </video>`;

    initDropboxVideos(document);

    const video = document.getElementById('v') as HTMLVideoElement;
    expect(video.muted).toBe(true);
    expect(video.defaultMuted).toBe(true);
    expect(video.playsInline).toBe(true);
    expect(play).toHaveBeenCalled();
  });

  it('retries play when the element becomes decodable', () => {
    const play = vi.fn(() => Promise.resolve());
    (HTMLMediaElement.prototype as unknown as { play: () => Promise<void> }).play = play;

    document.body.innerHTML = '<video id="v" autoplay loop muted></video>';
    initDropboxVideos(document);
    const callsAfterInit = play.mock.calls.length;

    document.getElementById('v')!.dispatchEvent(new Event('canplay'));
    expect(play.mock.calls.length).toBeGreaterThan(callsAfterInit);
  });

  it('leaves a non-autoplay video alone', () => {
    const play = vi.fn(() => Promise.resolve());
    (HTMLMediaElement.prototype as unknown as { play: () => Promise<void> }).play = play;

    document.body.innerHTML = '<video id="v" controls></video>';
    expect(initDropboxVideos(document)).toBeUndefined();
    expect(play).not.toHaveBeenCalled();
  });

  it('survives a play() that throws synchronously', () => {
    (HTMLMediaElement.prototype as unknown as { play: () => Promise<void> }).play = () => {
      throw new Error('not implemented');
    };
    document.body.innerHTML = '<video id="v" autoplay muted></video>';
    expect(() => initDropboxVideos(document)).not.toThrow();
  });
});

/* -------------------------------------------------- drift vs. real artifacts */

/** Every `className="..."` token list in the generated components. */
function generatedClassLists(): string[][] {
  if (!existsSync(generatedDir)) return [];
  const lists: string[][] = [];
  for (const file of readdirSync(generatedDir).filter((f) => f.endsWith('.tsx'))) {
    const text = readFileSync(join(generatedDir, file), 'utf8');
    for (const match of text.matchAll(/className="([^"]+)"/g)) {
      lists.push(match[1].trim().split(/\s+/));
    }
  }
  return lists;
}

/** How many generated elements carry every class token of a class selector. */
function countMatchingElements(selector: string): number {
  const tokens = selector.split('.').filter(Boolean);
  return generatedClassLists().filter((list) => tokens.every((t) => list.includes(t))).length;
}

const hasGenerated = existsSync(join(generatedDir, 'manifest.json'));

describe.skipIf(!hasGenerated)('reveal pairs still match the captured markup', () => {
  // Measured in THIS run's capture. These counts are deliberately exact: if
  // Dropbox rebuilds and a hash rotates, or a section's card count changes,
  // this fails loudly instead of the page shipping blocks stuck at opacity 0.
  const expectedCarriers: Record<string, number> = {
    '.dwg-multi-block-card-entry-animation': 9,
    '._card_1b963_1._cardEntryAnimation_1b963_1': 3,
    '._mediaContainer_thadj_29': 1,
  };

  it('covers exactly the pairs the analyzer flagged as gating visibility', () => {
    expect(DROPBOX_REVEAL_PAIRS.map((p) => p.base).sort()).toEqual(
      Object.keys(expectedCarriers).sort(),
    );
  });

  it.each(DROPBOX_REVEAL_PAIRS.map((p) => [p.base, p] as const))(
    'base selector %s still matches its captured carriers',
    (base, pair) => {
      expect(
        countMatchingElements(base),
        `hash rotation? "${base}" no longer matches the generated markup`,
      ).toBe(expectedCarriers[base]);

      // If the visible class were already baked in, the reveal would ship
      // already-finished rather than animating.
      expect(countMatchingElements(`.${pair.visible}`)).toBe(0);
    },
  );

  it('still finds the clipped rail that groups the quote cards', () => {
    const pair = DROPBOX_REVEAL_PAIRS.find((p) => p.groupSelector);
    expect(pair, 'the rail pair lost its groupSelector').toBeDefined();
    expect(
      countMatchingElements(pair!.groupSelector!),
      `hash rotation? rail "${pair!.groupSelector}" is not in the generated markup`,
    ).toBeGreaterThan(0);
  });
});

describe.skipIf(!hasGenerated)('nav + video selectors still match the captured markup', () => {
  it('finds the 6 dropdown triggers, their panels and the burger', () => {
    const tsx = readFileSync(join(generatedDir, 'RootSection.tsx'), 'utf8');
    expect([...tsx.matchAll(/aria-haspopup="true"/g)].length).toBe(6);
    expect([...tsx.matchAll(/aria-controls="nav-item-/g)].length).toBe(6);
    expect(countMatchingElements('.dwg-nav-item__dropdown')).toBe(6);
    expect(countMatchingElements('.dwg-nav__hamburger-button')).toBe(1);
    expect(countMatchingElements('.dwg-nav-mobile-dropdown')).toBe(1);
    expect(countMatchingElements('.dwg-nav--universal')).toBe(1);
  });

  it('finds 4 autoplaying videos, every source self-hosted', () => {
    const tsx = readFileSync(join(generatedDir, 'RootSection.tsx'), 'utf8');
    expect([...tsx.matchAll(/<video\b/g)].length).toBe(4);
    expect([...tsx.matchAll(/autoPlay/g)].length).toBe(4);
    for (const match of tsx.matchAll(/type="video\/webm[^"]*"/g)) {
      expect(match[0]).toBeTruthy();
    }
    // Every non-empty video source must be a local /assets path.
    for (const match of tsx.matchAll(/src="([^"]*)"\s*\n?\s*type="video\//g)) {
      if (match[1]) expect(match[1].startsWith('/assets/')).toBe(true);
    }
  });
});

describe('every hand-written effect is actually registered', () => {
  // A correct-but-unregistered effect is exactly how a replica ships broken,
  // so the wiring is asserted, not assumed.
  const clientRuntime = readFileSync(join(root, 'app', 'ClientRuntime.tsx'), 'utf8');

  it.each(['dropboxReveals', 'dropboxNav', 'dropboxVideos', 'smoothAnchors'])(
    'registers %s',
    (name) => {
      expect(clientRuntime).toMatch(new RegExp(`name:\\s*'${name}'`));
    },
  );

  it('does NOT register the two generic effects that would fight this site', () => {
    // navToggle applies classes this site's CSS does not define; marquee would
    // clone an already-duplicated, already-CSS-animated ticker.
    expect(clientRuntime).not.toMatch(/name:\s*'navToggle'/);
    expect(clientRuntime).not.toMatch(/name:\s*'marquee'/);
  });
});

