/**
 * Letter-trail ("caterpillar") headline reveal.
 *
 * Ported 1:1 from the live page's own bundle: scrape/raw/js/intelligence.a7cda79c.js
 * (minified class `p`). Every constant below is the value read out of that file, so the
 * choreography matches the original frame-for-frame:
 *
 *   - the headline is split into per-word / per-letter spans,
 *   - a "dot train" walks letter by letter, revealing each letter 110ms after it arrives,
 *   - a coloured particle is spawned at every letter,
 *   - punctuation introduces an extra pause,
 *   - when the last letter is reached the root gains `is-filled`, which is what switches
 *     `.reveal-headline__gradient` from flat #0d0031 to the animated gradient.
 */

const TIME_SCALE = 1; // `ue` — original divides every duration by this
const LETTER_REVEAL_DELAY = 110; // `me`
const LETTER_STEP_MS = 20; // `fe` — overridable per element via data-letter-delay
const LINE_MOVE_MS = 110; // `pe`
const PARTICLE_MS = 430; // `ye`

/** `ve` — extra dwell time after specific characters. */
const PUNCTUATION_PAUSE: Record<string, number> = {
  '.': 520,
  '!': 620,
  '?': 620,
  ',': 240,
  ':': 320,
  ';': 340,
  '\u2014': 300, // em dash
  '\u2013': 300, // en dash
};

/** `_` — the particle colour ramp. */
const COLORS = [
  '#D6E8F8',
  '#C9FF98',
  '#F6EA00',
  '#FFB238',
  '#FF4D40',
  '#A30D0D',
  '#FF2AF8',
  '#236CFF',
];

const scale = (ms: number) => ms / TIME_SCALE;

type Point = { x: number; y: number; minParticleSize?: number };
type DotState = { point: Point };

/** `we` — grapheme-aware split so emoji/combining marks stay intact. */
function splitGraphemes(value: string): string[] {
  const intl = Intl as unknown as {
    Segmenter?: new (
      locale?: string | string[],
      options?: { granularity?: string },
    ) => { segment(input: string): Iterable<{ segment: string }> };
  };
  if (intl.Segmenter) {
    const segmenter = new intl.Segmenter(undefined, { granularity: 'grapheme' });
    return [...segmenter.segment(value)].map(({ segment }) => segment);
  }
  return Array.from(value);
}

export type LetterTrailOptions = {
  onStart?: () => void;
  onComplete?: () => void;
  /** `startDelay` — the #intro headline is given 500ms in the original. */
  startDelay?: number;
};

export class LetterTrail {
  private readonly root: HTMLElement;
  private readonly onStart?: () => void;
  private readonly onComplete?: () => void;
  private readonly startDelay: number;

  private readonly reducedMotion: MediaQueryList;
  private readonly onMotionChange: () => void;
  private readonly observer: IntersectionObserver | null = null;

  private wrapper: HTMLElement | null = null;
  private dotLayer: HTMLElement | null = null;
  private startTimer: number | null = null;

  /** Incremented on every (re)play so stale async loops bail out. */
  private run = 0;
  private started = false;
  private completed = false;

  constructor(root: HTMLElement, options: LetterTrailOptions = {}) {
    this.root = root;
    this.onStart = options.onStart;
    this.onComplete = options.onComplete;
    this.startDelay = options.startDelay ?? 0;
    this.reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
    this.onMotionChange = () => void this.play();

    // Idempotency guard: React can mount effects twice in development.
    if (root.classList.contains('letter-trail') || root.closest('.caterpillar')) {
      this.reducedMotion.addEventListener('change', this.onMotionChange);
      return;
    }

    const wrapper = document.createElement('div');
    wrapper.className = 'caterpillar';
    root.replaceWith(wrapper);
    wrapper.append(root);
    this.wrapper = wrapper;

    const dotLayer = document.createElement('div');
    dotLayer.className = 'dot-layer';
    dotLayer.setAttribute('aria-hidden', 'true');
    wrapper.append(dotLayer);
    this.dotLayer = dotLayer;

    this.splitLetters();

    this.observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          this.observer?.disconnect();
          const begin = () => {
            if (document.fonts?.ready) {
              document.fonts.ready.then(() => void this.play(), () => void this.play());
            } else {
              void this.play();
            }
          };
          if (this.startDelay > 0) {
            this.startTimer = window.setTimeout(begin, this.startDelay);
          } else {
            begin();
          }
        }
      },
      { threshold: 0, rootMargin: '0px 0px -25% 0px' },
    );
    this.observer.observe(root);
    this.reducedMotion.addEventListener('change', this.onMotionChange);
  }

  /** Wraps every word in `.letter-trail__word` and every grapheme in `.letter-trail__letter`. */
  private splitLetters(): void {
    const label = (this.root.textContent ?? '').trim().replace(/\s+/g, ' ');
    this.root.setAttribute('aria-label', label);
    let index = 0;

    const walk = (node: Element): void => {
      for (const child of [...node.childNodes]) {
        if (child.nodeType === Node.ELEMENT_NODE) {
          walk(child as Element);
          continue;
        }
        if (child.nodeType !== Node.TEXT_NODE) continue;
        const text = child.textContent ?? '';
        if (!text.trim()) continue;

        const fragment = document.createDocumentFragment();
        for (const chunk of text.split(/(\s+)/)) {
          if (!chunk) continue;
          if (/^\s+$/.test(chunk)) {
            fragment.append(document.createTextNode(' '));
            continue;
          }
          const word = document.createElement('span');
          word.className = 'letter-trail__word';
          word.setAttribute('aria-hidden', 'true');
          for (const grapheme of splitGraphemes(chunk)) {
            const letter = document.createElement('span');
            letter.className = 'letter-trail__letter';
            letter.dataset.letterIndex = String(index++);
            letter.textContent = grapheme;
            word.append(letter);
          }
          fragment.append(word);
        }
        child.replaceWith(fragment);
      }
    };

    walk(this.root);
    this.root.classList.add('letter-trail');
  }

  private letters(): HTMLElement[] {
    return [...this.root.querySelectorAll<HTMLElement>('.letter-trail__letter')];
  }

  /** Groups letters into visual lines by comparing their top edges (2px tolerance). */
  private lines(): { top: number; letters: HTMLElement[] }[] {
    const lines: { top: number; letters: HTMLElement[] }[] = [];
    for (const letter of this.letters()) {
      const rect = letter.getBoundingClientRect();
      let line = lines.find(({ top }) => Math.abs(top - rect.top) < 2);
      if (!line) {
        line = { top: rect.top, letters: [] };
        lines.push(line);
      }
      line.letters.push(letter);
    }
    return lines;
  }

  private pointFor(letter: HTMLElement): Point {
    const dotLayer = this.dotLayer!;
    const rect = letter.getBoundingClientRect();
    const layerRect = dotLayer.getBoundingClientRect();
    const layerFont = parseFloat(getComputedStyle(dotLayer).fontSize);
    const letterFont = parseFloat(getComputedStyle(letter).fontSize);
    const height = letterFont * 0.8;
    const minParticleSize =
      (Math.hypot(rect.width, height) + Math.max(6, letterFont * 0.25)) / (layerFont * 0.8);
    return this.keepInsideViewport({
      x: rect.left + rect.width / 2 - layerRect.left,
      y: rect.top + rect.height * 0.53 - layerRect.top,
      minParticleSize,
    });
  }

  /** Below 768px the train is clamped so particles never overflow the viewport. */
  private keepInsideViewport(point: Point): Point {
    if (window.innerWidth > 768) return point;
    const dotLayer = this.dotLayer!;
    const layerRect = dotLayer.getBoundingClientRect();
    const inset =
      16 +
      (parseFloat(getComputedStyle(dotLayer).fontSize) *
        Math.max(1.04, point.minParticleSize || 0) *
        1.22) /
        2;
    return {
      ...point,
      x: Math.max(
        inset - layerRect.left,
        Math.min(document.documentElement.clientWidth - inset - layerRect.left, point.x),
      ),
    };
  }

  private static transformFor(point: Point): string {
    return `translate3d(${point.x}px, ${point.y}px, 0)`;
  }

  private async animateTo(
    element: HTMLElement,
    state: DotState,
    target: Point,
    options: KeyframeAnimationOptions,
    run: number,
    path?: Point[],
  ): Promise<boolean> {
    if (run !== this.run) return false;
    const points = path || [state.point, target];
    const animation = element.animate(
      points.map((point) => ({ transform: LetterTrail.transformFor(point) })),
      { fill: 'forwards', ...options },
    );
    try {
      await animation.finished;
    } catch {
      return false;
    }
    if (run !== this.run) return false;
    state.point = target;
    element.style.transform = LetterTrail.transformFor(target);
    animation.cancel();
    return true;
  }

  private spawnParticle(point: Point, index: number, run: number): void {
    if (run !== this.run) return;
    const dotLayer = this.dotLayer!;
    const position = document.createElement('span');
    const particle = document.createElement('i');
    const size = Math.max(0.92 + (index % 4) * 0.04, point.minParticleSize || 0);
    const colorStops = COLORS.map((backgroundColor, i) => ({
      backgroundColor,
      offset: 0.18 + i * (0.72 / (COLORS.length - 1)),
    }));

    position.className = 'trail-particle-position';
    particle.className = 'trail-particle';
    position.style.transform = LetterTrail.transformFor(point);
    particle.style.setProperty('--particle-size', String(size));
    position.append(particle);
    dotLayer.insertBefore(position, dotLayer.querySelector('.dot-train'));

    particle
      .animate(
        [
          { transform: 'scale(0)', backgroundColor: COLORS[COLORS.length - 1], opacity: 0 },
          { transform: 'scale(0.55)', opacity: 1, offset: 0.12 },
          ...colorStops.map((stop, i) => ({
            ...stop,
            transform: `scale(${0.65 + Math.sin((i / 7) * Math.PI) * 0.57})`,
            opacity: 1,
          })),
          { transform: 'scale(0)', backgroundColor: COLORS[COLORS.length - 1], opacity: 0 },
        ] as Keyframe[],
        { duration: scale(PARTICLE_MS), easing: 'linear', fill: 'forwards' },
      )
      .finished.finally(() => position.remove())
      .catch(() => position.remove());
  }

  private async waitForPause(ms: number, run: number): Promise<boolean> {
    if (!ms) return true;
    await new Promise((resolve) => window.setTimeout(resolve, ms));
    return run === this.run;
  }

  /** The swooping 4-point path the train follows when wrapping to the next line. */
  private async moveBetweenLines(
    element: HTMLElement,
    state: DotState,
    from: Point,
    to: Point,
    run: number,
  ): Promise<boolean> {
    const drop = Math.max(34, to.y - from.y);
    return this.animateTo(
      element,
      state,
      to,
      { duration: scale(LINE_MOVE_MS), easing: 'cubic-bezier(0.55, 0, 0.2, 1)' },
      run,
      [
        from,
        this.keepInsideViewport({ x: from.x + 28, y: from.y + drop * 0.72 }),
        this.keepInsideViewport({ x: to.x - 46, y: to.y + 18 }),
        to,
      ],
    );
  }

  async play(): Promise<void> {
    if (!this.dotLayer) return;
    const run = ++this.run;
    this.dotLayer.replaceChildren();
    if (!this.started) {
      this.started = true;
      this.onStart?.();
    }

    const letters = this.letters();
    for (const letter of letters) letter.classList.remove('is-visible');

    if (this.reducedMotion.matches) {
      for (const letter of letters) letter.classList.add('is-visible');
      this.root.classList.add('is-filled');
      this.complete();
      return;
    }

    const lines = this.lines();
    if (!lines.length) return;

    const train = document.createElement('div');
    train.className = 'dot-train';
    this.dotLayer.append(train);

    const first = this.pointFor(lines[0].letters[0]);
    const state: DotState = { point: first };
    let particleIndex = 0;
    train.style.transform = LetterTrail.transformFor(first);

    const step = scale(Number(this.root.dataset.letterDelay) || LETTER_STEP_MS);

    for (let i = 0; i < lines.length; i += 1) {
      for (const letter of lines[i].letters) {
        if (run !== this.run) return;
        const point = this.pointFor(letter);
        if (!(await this.animateTo(train, state, point, { duration: step, easing: 'linear' }, run)))
          return;
        this.spawnParticle(point, particleIndex++, run);
        window.setTimeout(() => {
          if (run === this.run) letter.classList.add('is-visible');
        }, scale(LETTER_REVEAL_DELAY));
        const pause = PUNCTUATION_PAUSE[letter.textContent ?? ''] || 0;
        if (!(await this.waitForPause(scale(pause), run))) return;
      }
      const nextLine = lines[i + 1];
      if (!nextLine) break;
      const target = this.pointFor(nextLine.letters[0]);
      if (!(await this.moveBetweenLines(train, state, state.point, target, run))) return;
    }

    if (run === this.run) {
      train.remove();
      this.root.classList.add('is-filled');
      this.complete();
    }
  }

  private complete(): void {
    if (this.completed) return;
    this.completed = true;
    this.onComplete?.();
  }

  destroy(): void {
    this.run += 1;
    if (this.startTimer !== null) window.clearTimeout(this.startTimer);
    this.observer?.disconnect();
    this.reducedMotion.removeEventListener('change', this.onMotionChange);
    this.dotLayer?.remove();
    if (this.wrapper?.parentNode) this.wrapper.replaceWith(this.root);
  }
}

/**
 * Attaches a letter trail to every `.reveal-headline`, optionally skipping ones already
 * owned by another controller (the hero orchestrator owns `#intro .reveal-headline`).
 */
export function initLetterTrails(
  scope: ParentNode = document,
  skip: Element[] = [],
): () => void {
  const roots = [...scope.querySelectorAll<HTMLElement>('.reveal-headline')].filter(
    (root) => !skip.includes(root),
  );
  const trails = roots.map((root) => new LetterTrail(root));
  return () => {
    for (const trail of trails) trail.destroy();
  };
}

/**
 * Hero word entry + propeller-clip choreography.
 *
 * Ported 1:1 from the live page's own bundle: scrape/raw/js/intelligence.a7cda79c.js
 * (minified class `B` plus the module-level orchestration block at the end of that file).
 *
 * Why this module is mandatory rather than decorative: the page's base CSS ships
 * `.hero__word-inner{opacity:0;transform:translate(48px)}` unconditionally, so without this
 * controller writing inline styles the entire hero headline stays invisible.
 *
 * Sequence:
 *   1. words fade/slide in on a tightening stagger (700ms, then 300ms -> 200ms steps),
 *   2. the propeller clip plays and pauses itself at 1.8s ("hold"),
 *   3. the first wheel/touch/key gesture resumes it; scrolling past the threshold instead
 *      snaps everything to its final state,
 *   4. once the clip finishes the hero dims, #intro is scrolled into view, and the clip
 *      "flies" to the intro statement then freezes into its poster still.
 */

import { LetterTrail } from './intuitLetterTrail';

const ENTRY_FIRST_DELAY = 700; // `ie`
const ENTRY_STEP_START = 300; // `I`
const ENTRY_STEP_END = 200; // `re`
const WORD_TRANSFORM_MS = 300; // `b`
const WORD_OFFSET_PX = 48; // `F`
const WORD_OPACITY_MS = 260; // `N`
const WORD_EASE = 'cubic-bezier(0.25,0.46,0.45,0.94)'; // `oe`
const HOLD_AT_SECONDS = 1.8; // `A`
const MARGIN_DELAY_MS = 800; // `ne`
const MARGIN_MS = 500; // `O`
const MARGIN_EASE = 'ease-out'; // `D`
const MARGIN_INLINE = '-0.25em'; // `ae`
const VIDEO_LIFT = 'translateY(6%)'; // `le`
const FLY_MS = 600; // `M`
const FLY_EASE = 'cubic-bezier(0.4,0,0.2,1)'; // `ce`
const FADE_MS = 300; // `q`
const FLY_ANCHOR_X = 0.25; // `he`
const FLY_ANCHOR_Y = 0.25; // `de`

/** `Ce` — the intro headline's letter trail waits this long before starting. */
const INTRO_TRAIL_DELAY = 500;
/** Scroll threshold for "user has moved on": max(18% of viewport, 120px). */
const SCROLL_THRESHOLD_RATIO = 0.18;
const SCROLL_THRESHOLD_MIN = 120;
/** Fallback if the hero's background-color transition never reports. */
const DIM_FALLBACK_MS = 900;

const prefersReducedMotion = () =>
  window.matchMedia('(prefers-reduced-motion: reduce)').matches;

export type HeroOptions = {
  onComplete?: () => void;
  onHold?: () => void;
};

export class Hero {
  private readonly root: HTMLElement;
  private readonly onComplete?: () => void;
  private readonly onHold?: () => void;

  private readonly words: HTMLElement[];
  private readonly inners: (HTMLElement | null)[] = [];
  private video: HTMLVideoElement | null = null;
  private entryTimers: number[] = [];

  private readonly reduced: boolean;
  private entryPlayed = false;
  private completed = false;
  private playThrough = false;
  private propellerStarted = false;
  private holding = false;
  private resumed = false;
  private settled = false;
  private detached = false;
  private flown = false;
  private flightActive = false;
  private frozen = false;
  private finishedInstantly = false;
  private gestureRetryArmed = false;

  private placeholder: HTMLElement | null = null;
  private flightHome: DOMRect | null = null;
  private onEnded: (() => void) | null = null;
  private onPauseTime: (() => void) | null = null;

  constructor(root: HTMLElement, options: HeroOptions = {}) {
    this.root = root;
    this.onComplete = options.onComplete;
    this.onHold = options.onHold;
    this.words = Array.from(root.querySelectorAll<HTMLElement>('.hero__word'));
    this.reduced = prefersReducedMotion();

    if (!this.words.length) return;

    this.inners = this.words.map((word) =>
      word.querySelector<HTMLElement>('.hero__word-inner'),
    );
    this.video = root.querySelector<HTMLVideoElement>('.hero__propeller-video');

    if (this.video) {
      this.video.pause();
      this.video.currentTime = 0;
    }

    root.classList.add('is-animating');

    if (this.reduced) {
      root.classList.remove('is-animating');
      this.enterHold();
      return;
    }

    const start = () => this.playEntry();
    if (document.fonts?.status === 'loaded') start();
    else if (document.fonts) document.fonts.ready.then(start, start);
    else start();
  }

  private playEntry(): void {
    if (this.entryPlayed) return;
    this.entryPlayed = true;

    // Build the per-word delay table: the gap between words tightens from 300ms to 200ms.
    const delays: number[] = [];
    let cursor = ENTRY_FIRST_DELAY;
    const span = Math.max(this.words.length - 1, 1);
    this.words.forEach((_word, index) => {
      delays.push(cursor);
      const progress = Math.min(index, span - 1) / span;
      cursor += ENTRY_STEP_START + (ENTRY_STEP_END - ENTRY_STEP_START) * progress;
    });

    const offsetFor = (inner: HTMLElement) =>
      inner.classList.contains('hero__propeller')
        ? `translate(${WORD_OFFSET_PX}px, -0.04em)`
        : `translateX(${WORD_OFFSET_PX}px)`;

    for (const inner of this.inners) {
      if (!inner) continue;
      inner.style.opacity = '0';
      inner.style.transform = offsetFor(inner);
    }

    this.root.classList.remove('is-animating');

    this.inners.forEach((inner, index) => {
      if (!inner) return;
      this.entryTimers.push(
        window.setTimeout(() => {
          inner.style.transition = `opacity ${WORD_OPACITY_MS}ms ease`;
          inner.style.opacity = '1';
        }, delays[index]),
      );
      const slideAt =
        index < this.words.length - 1
          ? delays[index + 1]
          : delays[index] + WORD_TRANSFORM_MS * 0.3;
      this.entryTimers.push(
        window.setTimeout(() => {
          // Force a style read so the transition actually applies from the offset position.
          void getComputedStyle(inner).transform;
          inner.style.transition = `opacity ${WORD_OPACITY_MS}ms ease, transform ${WORD_TRANSFORM_MS}ms ${WORD_EASE}`;
          inner.style.transform = inner.classList.contains('hero__propeller')
            ? 'translateY(-0.04em)'
            : 'translate(0px, 0px)';
        }, slideAt),
      );
    });

    const propellerAt = delays[this.words.length - 1] + WORD_TRANSFORM_MS;
    this.entryTimers.push(window.setTimeout(() => this.startPropeller(), propellerAt));
  }

  private startPropeller(): void {
    this.propellerStarted = true;
    if (!this.video) {
      this.enterHold();
      return;
    }
    if (this.playThrough) {
      this.freeze();
      return;
    }

    this.video.muted = true;
    this.video.setAttribute('muted', '');

    if (this.resumed) {
      this.onEnded = () => this.settleClip();
      this.video.addEventListener('ended', this.onEnded);
      const duration = Number.isFinite(this.video.duration) ? this.video.duration : 3;
      this.entryTimers.push(
        window.setTimeout(() => this.settleClip(), duration * 1000 + 600),
      );
      this.video.currentTime = 0;
      const played = this.video.play();
      if (played) played.catch(() => this.settleClip());
      this.animatePropellerMargin();
      return;
    }

    // Not yet resumed: run the clip up to 1.8s, then pause and wait for the user.
    this.onPauseTime = () => {
      if (!this.video || this.video.currentTime < HOLD_AT_SECONDS) return;
      if (this.onPauseTime) this.video.removeEventListener('timeupdate', this.onPauseTime);
      this.onPauseTime = null;
      this.video.pause();
      this.video.currentTime = HOLD_AT_SECONDS;
      this.enterHold();
    };
    this.video.addEventListener('timeupdate', this.onPauseTime);
    this.video.currentTime = 0;
    this.video.muted = true;
    this.video.setAttribute('muted', '');
    this.attemptPlay();
  }

  private enterHold(): void {
    if (this.holding || this.resumed) return;
    this.holding = true;
    this.onHold?.();
  }

  resume(): void {
    if (this.resumed) return;
    this.resumed = true;
    this.holding = false;
    if (this.playThrough) return;

    if (!this.video) {
      this.settleClip();
      return;
    }
    if (!this.propellerStarted) return;

    if (this.onPauseTime) {
      this.video.removeEventListener('timeupdate', this.onPauseTime);
      this.onPauseTime = null;
    }
    this.onEnded = () => this.settleClip();
    this.video.addEventListener('ended', this.onEnded);
    const remaining = Number.isFinite(this.video.duration)
      ? Math.max(this.video.duration - this.video.currentTime, 0)
      : 1;
    this.entryTimers.push(
      window.setTimeout(() => this.settleClip(), remaining * 1000 + 600),
    );
    const played = this.video.play();
    if (played) played.catch(() => this.settleClip());
  }

  /** Autoplay may be refused; if so, arm one-shot gesture listeners and retry. */
  private attemptPlay(): void {
    if (!this.video) return;
    const onOk = () => {
      this.animatePropellerMargin();
      this.entryTimers.push(
        window.setTimeout(() => this.enterHold(), HOLD_AT_SECONDS * 1000 + 600),
      );
    };
    const onFail = () => {
      if (this.gestureRetryArmed) return;
      this.gestureRetryArmed = true;
      const events = ['pointerdown', 'touchstart', 'keydown'];
      const retry = () => {
        for (const event of events) window.removeEventListener(event, retry);
        if (!this.video || this.resumed) return;
        this.video.play().then(onOk, () => this.enterHold());
      };
      for (const event of events) {
        window.addEventListener(event, retry, { passive: true, once: true });
      }
    };
    this.video.play().then(onOk, onFail);
  }

  private settleClip(): void {
    if (this.settled) return;
    this.settled = true;
    if (this.video && this.onEnded) {
      this.video.removeEventListener('ended', this.onEnded);
      this.onEnded = null;
    }
    this.detachClip();
    this.complete();
  }

  /** Slides the propeller word tighter and lifts the clip slightly, 800ms in. */
  private animatePropellerMargin(): void {
    const propeller = this.root.querySelector<HTMLElement>('.hero__propeller');
    if (!propeller) return;
    const video = this.video;
    this.entryTimers.push(
      window.setTimeout(() => {
        propeller.style.transition = `margin-inline ${MARGIN_MS}ms ${MARGIN_EASE}`;
        propeller.style.marginInline = MARGIN_INLINE;
        if (video) {
          video.style.transition = `transform ${MARGIN_MS}ms ${MARGIN_EASE}`;
          video.style.transform = VIDEO_LIFT;
        }
      }, MARGIN_DELAY_MS),
    );
  }

  /** Lifts the clip out of the text flow into a fixed-position element it can fly from. */
  private detachClip(): void {
    if (!this.video || this.detached) return;
    this.detached = true;
    const rect = this.video.getBoundingClientRect();
    const propeller = this.video.closest<HTMLElement>('.hero__propeller');

    if (propeller) {
      const placeholder = document.createElement('span');
      placeholder.className = 'hero__propeller-placeholder';
      placeholder.style.width = `${rect.width}px`;
      placeholder.style.height = `${rect.height}px`;
      propeller.appendChild(placeholder);
      this.placeholder = placeholder;
    }

    const video = this.video;
    video.style.transition = 'none';
    video.style.position = 'fixed';
    video.style.margin = '0';
    video.style.left = `${rect.left}px`;
    video.style.top = `${rect.top}px`;
    video.style.width = `${rect.width}px`;
    video.style.height = `${rect.height}px`;
    video.style.transformOrigin = 'top left';
    video.style.transform = 'translate(0, 0) scale(1)';
    video.style.zIndex = '5';
    video.style.pointerEvents = 'none';
    document.body.appendChild(video);
    this.flightHome = rect;
  }

  /** Flies the detached clip toward `target` (the intro statement), then fades it out. */
  flyClipTo(target: Element | null, targetRect?: DOMRect): void {
    if (!this.video || this.flown) return;
    if (!this.detached) this.settleClip();
    if (!this.video || !this.detached) return;

    this.flown = true;
    this.flightActive = true;
    const video = this.video;

    if ((!target && !targetRect) || this.reduced) {
      this.fadeOutClip();
      return;
    }

    const home = this.flightHome || video.getBoundingClientRect();
    const destination = targetRect || (target as Element).getBoundingClientRect();
    const dx =
      destination.left - (home.left + home.width / 2) + home.width * FLY_ANCHOR_X;
    const dy = destination.top - (home.top + home.height / 2) + home.height * FLY_ANCHOR_Y;

    void getComputedStyle(video).transform;
    video.style.transition = `transform ${FLY_MS}ms ${FLY_EASE}`;
    video.style.transform = `translate(${dx}px, ${dy}px)`;
    this.entryTimers.push(window.setTimeout(() => this.fadeOutClip(), FLY_MS));
  }

  private fadeOutClip(): void {
    const video = this.video;
    if (!video) return;
    video.style.transition = `${
      video.style.transition ? `${video.style.transition}, ` : ''
    }opacity ${FADE_MS}ms ease`;
    void getComputedStyle(video).opacity;
    video.style.opacity = '0';
    this.entryTimers.push(
      window.setTimeout(() => {
        this.flightActive = false;
        this.freeze();
      }, FADE_MS),
    );
  }

  /** Snaps everything to its end state without animating (user scrolled away). */
  finishInstantly(): void {
    if (this.finishedInstantly) return;
    this.finishedInstantly = true;
    for (const timer of this.entryTimers) window.clearTimeout(timer);
    this.entryTimers = [];
    this.root.classList.remove('is-animating');

    for (const inner of this.inners) {
      if (!inner) continue;
      inner.style.transition = 'none';
      inner.style.opacity = '1';
      inner.style.transform = inner.classList.contains('hero__propeller')
        ? 'translateY(-0.04em)'
        : 'translate(0px, 0px)';
    }

    const propeller = this.root.querySelector<HTMLElement>('.hero__propeller');
    if (propeller) {
      propeller.style.transition = 'none';
      propeller.style.marginInline = '';
    }
    this.letVideoFinish();
  }

  private letVideoFinish(): void {
    if (this.playThrough) return;
    this.playThrough = true;
    this.completed = true;
    if (!this.video) return;
    this.video.pause();
    if (this.onEnded) {
      this.video.removeEventListener('ended', this.onEnded);
      this.onEnded = null;
    }
    if (this.onPauseTime) {
      this.video.removeEventListener('timeupdate', this.onPauseTime);
      this.onPauseTime = null;
    }
    this.flightActive = false;
    this.freeze();
  }

  private complete(): void {
    if (this.completed) return;
    this.completed = true;
    this.onComplete?.();
  }

  /** Replaces the video element with its poster frame so nothing keeps decoding. */
  freeze(): void {
    if (!this.video || this.frozen || this.flightActive) return;
    this.frozen = true;
    document.body.style.background = '#fff';

    const poster = this.video.getAttribute('poster');
    if (!poster) return;

    const still = document.createElement('img');
    still.className = 'hero__propeller-still';
    still.src = poster;
    still.alt = '';
    still.setAttribute('aria-hidden', 'true');

    const host =
      this.placeholder?.closest<HTMLElement>('.hero__propeller') ||
      this.video.closest<HTMLElement>('.hero__propeller');
    if (host) host.style.marginInline = '';

    if (this.detached) {
      if (this.placeholder) {
        this.placeholder.replaceWith(still);
        this.placeholder = null;
      } else if (host) {
        host.appendChild(still);
      }
      this.video.remove();
    } else {
      this.video.replaceWith(still);
    }

    this.onEnded = null;
    this.video = null;
  }

  destroy(): void {
    for (const timer of this.entryTimers) window.clearTimeout(timer);
    this.entryTimers = [];
    if (this.video && this.onEnded) this.video.removeEventListener('ended', this.onEnded);
    if (this.video && this.onPauseTime) {
      this.video.removeEventListener('timeupdate', this.onPauseTime);
    }
    if (this.detached && this.video) this.video.remove();
    this.placeholder?.remove();
  }
}

/**
 * Wires the hero to #intro exactly as the original module-level block does, and returns the
 * `.reveal-headline` element it has taken ownership of (so the generic letter-trail
 * initialiser can skip it) plus a teardown function.
 */
export function initHero(): { owned: Element[]; destroy: () => void } {
  const hero = document.querySelector<HTMLElement>('.hero');
  const intro = document.querySelector<HTMLElement>('#intro');
  const headline = document.querySelector<HTMLElement>('#intro .reveal-headline');
  // Note: on this page `.intro__statement` and the intro `.reveal-headline` are the same node.
  const statement = document.querySelector<HTMLElement>('#intro .intro__statement');

  const cleanups: (() => void)[] = [];
  const owned: Element[] = [];
  let controller: Hero | null = null;

  if (hero && intro && headline) {
    const undim = () => hero.classList.remove('is-dimmed');
    let resumedOnce = false;
    let dimming = false;
    let bailedOut = false;

    const gestureEvents = ['wheel', 'touchmove', 'keydown'];
    const removeGestures = () => {
      for (const event of gestureEvents) {
        window.removeEventListener(event, onGesture as EventListener);
      }
    };

    const threshold = () =>
      Math.max(window.innerHeight * SCROLL_THRESHOLD_RATIO, SCROLL_THRESHOLD_MIN);
    const onScroll = () => {
      if (dimming || bailedOut) return;
      if (window.scrollY > threshold()) bailOut();
    };
    const removeScroll = () => window.removeEventListener('scroll', onScroll);

    const resume = () => {
      if (resumedOnce || bailedOut) return;
      resumedOnce = true;
      controller?.resume();
    };

    const bailOut = () => {
      if (bailedOut || dimming) return;
      bailedOut = true;
      removeGestures();
      removeScroll();
      undim();
      controller?.finishInstantly();
    };

    const NAV_KEYS = new Set([
      'ArrowUp',
      'ArrowDown',
      'PageUp',
      'PageDown',
      'Home',
      'End',
      ' ',
    ]);

    function onGesture(event: WheelEvent | TouchEvent | KeyboardEvent): void {
      if (document.documentElement.classList.contains('nav-open')) return;
      if (event.defaultPrevented) return;
      const modified = event as unknown as {
        ctrlKey?: boolean;
        metaKey?: boolean;
        altKey?: boolean;
      };
      if (modified.ctrlKey || modified.metaKey || modified.altKey) return;
      if (event.type === 'keydown') {
        const key = (event as KeyboardEvent).key;
        const target = event.target;
        if (
          !NAV_KEYS.has(key) ||
          (target instanceof Element &&
            target.closest(
              "input, textarea, select, button, a, [contenteditable]:not([contenteditable='false']), [role='textbox']",
            ))
        ) {
          return;
        }
      }
      if (event.type === 'wheel' && (event as WheelEvent).deltaY === 0) return;
      if (event.type === 'touchmove' && (event as TouchEvent).touches.length !== 1) return;
      if (event.cancelable) event.preventDefault();
      resume();
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    for (const event of gestureEvents) {
      window.addEventListener(event, onGesture as EventListener, { passive: false });
    }

    /** Dim the hero, jump to #intro, then fly the clip to the intro statement. */
    const dimAndAdvance = () => {
      if (dimming || bailedOut) return;
      dimming = true;
      removeScroll();
      let advanced = false;

      const advance = () => {
        if (advanced) return;
        advanced = true;
        removeGestures();
        hero.removeEventListener('transitionend', onTransitionEnd);
        intro.scrollIntoView({ block: 'start', behavior: 'instant' as ScrollBehavior });
        undim();
        const fly = () => {
          if (!statement) {
            controller?.flyClipTo(statement);
            return;
          }
          controller?.flyClipTo(statement, statement.getBoundingClientRect());
        };
        requestAnimationFrame(() => requestAnimationFrame(fly));
      };

      const onTransitionEnd = (event: TransitionEvent) => {
        if (event.target === hero && event.propertyName === 'background-color') advance();
      };

      hero.addEventListener('transitionend', onTransitionEnd);
      window.setTimeout(advance, DIM_FALLBACK_MS);
      hero.classList.add('is-dimmed');
    };

    controller = new Hero(hero, {
      onComplete: () => {
        if (!bailedOut) dimAndAdvance();
      },
    });

    const trail = new LetterTrail(headline, {
      onStart: () => controller?.freeze(),
      startDelay: INTRO_TRAIL_DELAY,
    });
    owned.push(headline);

    const chevronAction = () => {
      if (bailedOut || dimming) {
        intro.scrollIntoView({
          behavior: prefersReducedMotion() ? 'auto' : 'smooth',
          block: 'start',
        });
      } else if (resumedOnce) {
        dimAndAdvance();
      } else {
        resume();
      }
    };

    const chevron = hero.querySelector<HTMLElement>('.hero__chevron');
    if (chevron) {
      const onChevron = (event: Event) => {
        event.preventDefault();
        chevronAction();
      };
      chevron.addEventListener('click', onChevron);
      cleanups.push(() => chevron.removeEventListener('click', onChevron));
    }

    cleanups.push(() => {
      removeGestures();
      removeScroll();
      trail.destroy();
      controller?.destroy();
    });
  } else if (hero) {
    // No #intro to advance to: still run the entry animation so the words become visible.
    const standalone = new Hero(hero);
    cleanups.push(() => standalone.destroy());
  }

  return {
    owned,
    destroy: () => {
      for (const cleanup of cleanups) cleanup();
    },
  };
}

/**
 * Video players + the tabbed banner that drives them.
 *
 * Ported from the live page's own bundle: scrape/raw/js/prefooter.a922aff5.js
 * (minified class `F` = video player, class `I` = tabbed banner). The two are coupled
 * through a WeakMap registry: selecting a tab calls `setSelected()` on the player inside
 * that panel, and the tab's progress bar is driven by that video's `currentTime`.
 *
 * Both are mandatory for correct rendering, not just motion:
 *   - `.video-player` is `opacity:0;transform:translateY(24px)` until `is-visible`,
 *   - `.tabbed-banner__panel` is `opacity:0;visibility:hidden` until `is-active`, and the
 *     captured SSR markup marks *all four* panels `is-active`, so `select(0)` on mount is
 *     what collapses them down to the single visible panel.
 */

const DEFAULT_TAB_MS = 6000; // `E` — fallback when a tab has no video
const PAUSE_ON_HOVER = false; // `b` — present in the original but hard-disabled
const SWIPE_MIN_PX = 45; // `S`
const SWIPE_RATIO = 1.4; // `T`

/** Shared registry so the tabbed banner can reach the player inside each panel. */
const players = new WeakMap<HTMLVideoElement, VideoPlayer>();

/**
 * `Kt` from disclaimer.js: re-points a <video> at whichever <source media> matches now.
 * This page ships no `source[media]` elements (verified: 0 in the captured markup), so
 * there is never a source to swap and this always reports "unchanged".
 */
function syncSource(video: HTMLVideoElement): boolean {
  const sources = [...video.querySelectorAll<HTMLSourceElement>('source[media]')];
  if (!sources.length) return false;
  const match = sources.find((source) => window.matchMedia(source.media).matches);
  const next = match?.src;
  if (!next) return false;
  const current = video.getAttribute('src') || video.currentSrc;
  if (current && new URL(current, document.baseURI).href === new URL(next, document.baseURI).href) {
    return false;
  }
  video.src = next;
  return true;
}

type PlaybackOptions = { onPlaying?: () => void; onFailure?: () => void };

/**
 * `Zt` from disclaimer.js: keeps a muted video playing while it is "active", and copes with
 * browsers that refuse autoplay by retrying after the first user gesture.
 */
class PlaybackManager {
  private readonly video: HTMLVideoElement;
  private readonly options: PlaybackOptions;
  private active = false;
  private destroyed = false;
  private gestureArmed = false;

  constructor(video: HTMLVideoElement, options: PlaybackOptions = {}) {
    this.video = video;
    this.options = options;
  }

  setActive(active: boolean): void {
    if (this.destroyed || this.active === active) return;
    this.active = active;
    if (active) this.attempt();
    else this.video.pause();
  }

  attempt(force = false): void {
    if (this.destroyed) return;
    if (force) this.active = true;
    if (!this.active) return;
    this.video.muted = true;
    const played = this.video.play();
    if (!played) {
      this.options.onPlaying?.();
      return;
    }
    played.then(
      () => this.options.onPlaying?.(),
      () => {
        this.options.onFailure?.();
        this.armGestureRetry();
      },
    );
  }

  private armGestureRetry(): void {
    if (this.gestureArmed) return;
    this.gestureArmed = true;
    const events = ['pointerdown', 'touchstart', 'keydown'];
    const retry = () => {
      for (const event of events) window.removeEventListener(event, retry);
      this.gestureArmed = false;
      if (!this.destroyed && this.active) this.attempt();
    };
    for (const event of events) {
      window.addEventListener(event, retry, { passive: true, once: true });
    }
  }

  destroy(): void {
    this.destroyed = true;
    this.active = false;
  }
}

export class VideoPlayer {
  private readonly root: HTMLElement;
  private readonly video: HTMLVideoElement | null;
  private readonly replay: HTMLElement | null = null;
  private readonly queries: MediaQueryList[] = [];
  private readonly observer: IntersectionObserver | null = null;

  private playback: PlaybackManager | null = null;
  private selected = false;
  private visible = false;
  private restart = false;
  private destroyed = false;
  private sourceFrame = 0;
  private pendingFinalSource: string | null = null;
  private onCompletedMetadata: (() => void) | null = null;

  /** Read by the tabbed banner to know when to advance. */
  completed = false;

  private readonly onEnded: () => void;
  private readonly onReplay: () => void;
  private readonly onSourceChange: () => void;

  constructor(root: HTMLElement) {
    this.root = root;
    this.video = root.querySelector<HTMLVideoElement>('video');

    if (!this.video) {
      this.onEnded = () => {};
      this.onReplay = () => {};
      this.onSourceChange = () => {};
      return;
    }

    players.set(this.video, this);
    this.video.dataset.playbackOwned = 'true';
    this.video.muted = true;
    this.video.playsInline = true;
    this.video.loop = false;
    this.video.pause();

    // Players outside a tab panel own themselves; ones inside wait to be selected.
    this.selected = !root.closest('.tabbed-banner__panel');

    this.replay = root.querySelector<HTMLElement>('.video-player__replay');

    this.onEnded = () => {
      this.completed = true;
      this.playback?.setActive(false);
      root.classList.add('is-ended');
    };
    this.video.addEventListener('ended', this.onEnded);

    this.onReplay = () => {
      this.cancelCompletedSeek();
      this.pendingFinalSource = null;
      this.completed = false;
      this.restart = true;
      this.sync();
      this.playback?.attempt(true);
    };
    this.replay?.addEventListener('click', this.onReplay);

    this.queries = [
      ...new Set(
        [...this.video.querySelectorAll<HTMLSourceElement>('source[media]')].map(
          (source) => source.media,
        ),
      ),
    ].map((media) => window.matchMedia(media));

    this.onSourceChange = () => {
      window.cancelAnimationFrame(this.sourceFrame);
      this.sourceFrame = window.requestAnimationFrame(() => this.sync());
    };
    for (const query of this.queries) query.addEventListener('change', this.onSourceChange);

    if ('IntersectionObserver' in window) {
      this.observer = new IntersectionObserver(
        ([entry]) => {
          this.visible = entry.isIntersecting;
          this.sync();
        },
        { threshold: 0, rootMargin: '0px 0px -20% 0px' },
      );
      this.observer.observe(root);
    } else {
      this.visible = true;
      this.sync();
    }
  }

  setSelected(selected: boolean, { restart = false }: { restart?: boolean } = {}): void {
    this.selected = selected;
    if (restart) {
      this.cancelCompletedSeek();
      this.pendingFinalSource = null;
      this.restart = true;
      this.completed = false;
    }
    this.sync();
  }

  sync(): void {
    if (this.destroyed || !this.video) return;

    if (!this.selected || !this.visible) {
      this.cancelCompletedSeek();
      this.playback?.setActive(false);
      return;
    }

    // This is the class that reveals the player at all.
    this.root.classList.add('is-visible');
    if (this.completed) this.playback?.setActive(false);

    const sourceChanged = syncSource(this.video);
    if (sourceChanged || !this.playback) {
      this.cancelCompletedSeek();
      this.playback?.destroy();
      this.playback = new PlaybackManager(this.video, {
        onPlaying: () => this.root.classList.remove('is-ended'),
        onFailure: () => this.root.classList.add('is-ended'),
      });
    }

    if (this.completed) {
      if (sourceChanged) {
        this.pendingFinalSource = this.video.src;
        this.video.preload = 'auto';
        this.video.load();
      }
      if (this.pendingFinalSource) this.restoreCompletedFrame();
      return;
    }

    if (this.restart) {
      this.playback!.setActive(false);
      this.video.currentTime = 0;
      this.restart = false;
    }
    this.playback!.setActive(true);
  }

  private cancelCompletedSeek(): void {
    if (!this.onCompletedMetadata) return;
    for (const event of ['loadedmetadata', 'loadeddata', 'seeked']) {
      this.video?.removeEventListener(event, this.onCompletedMetadata);
    }
    this.onCompletedMetadata = null;
  }

  /** After a source swap on an already-finished video, park it on its final frame. */
  private restoreCompletedFrame(): void {
    this.cancelCompletedSeek();
    if (!this.video) return;
    const expected = this.pendingFinalSource;
    let seeked = false;

    const settle = () => {
      if (
        this.destroyed ||
        !this.completed ||
        !this.selected ||
        !this.visible ||
        !this.video ||
        this.pendingFinalSource !== expected ||
        this.video.currentSrc !== expected ||
        this.video.readyState < 1 ||
        !Number.isFinite(this.video.duration)
      ) {
        return;
      }
      this.video.pause();
      if (!seeked) {
        seeked = true;
        this.video.currentTime = this.video.duration;
      }
      if (
        this.video.readyState >= 2 &&
        !this.video.seeking &&
        Math.abs(this.video.currentTime - this.video.duration) < 1e-6
      ) {
        this.pendingFinalSource = null;
        this.cancelCompletedSeek();
      }
    };

    this.onCompletedMetadata = settle;
    for (const event of ['loadedmetadata', 'loadeddata', 'seeked']) {
      this.video.addEventListener(event, settle);
    }
    settle();
  }

  destroy(): void {
    this.destroyed = true;
    this.cancelCompletedSeek();
    this.observer?.disconnect();
    window.cancelAnimationFrame(this.sourceFrame);
    for (const query of this.queries) {
      query.removeEventListener('change', this.onSourceChange);
    }
    this.video?.removeEventListener('ended', this.onEnded);
    this.replay?.removeEventListener('click', this.onReplay);
    this.playback?.destroy();
    if (this.video) players.delete(this.video);
  }
}

export class TabbedBanner {
  private readonly root: HTMLElement;
  private readonly tabs: HTMLElement[];
  private readonly panels: HTMLElement[];
  private readonly tabList: HTMLElement | null = null;
  private readonly banner: HTMLElement | null = null;
  private readonly observer: IntersectionObserver | null = null;

  private index = 0;
  private elapsed = 0;
  private lastFrame = 0;
  private lastVideoTime = 0;
  private rafId: number | null = null;
  private manual = false;
  private inView = false;
  private hoverTab = false;
  private hoverBanner = false;
  private activeVideo: HTMLVideoElement | null = null;
  private readonly cleanups: (() => void)[] = [];

  constructor(root: HTMLElement) {
    this.root = root;
    this.tabs = Array.from(root.querySelectorAll<HTMLElement>('.tabbed-banner__tab'));
    this.panels = Array.from(root.querySelectorAll<HTMLElement>('.tabbed-banner__panel'));
    if (!this.tabs.length) return;

    this.tabList = root.querySelector<HTMLElement>('.tabbed-banner__tabs ul');
    this.banner = root.querySelector<HTMLElement>('.tabbed-banner__banner');

    this.bind();
    // Collapses the all-`is-active` SSR markup down to a single visible panel.
    this.select(0, { resetProgress: true });
    requestAnimationFrame(() => this.root.classList.add('is-ready'));

    this.observer = new IntersectionObserver(
      ([entry]) => this.onVisibility(entry.isIntersecting),
      { threshold: 0.35 },
    );
    this.observer.observe(root);
  }

  private bind(): void {
    this.tabs.forEach((tab, index) => {
      const onClick = () => {
        if (index !== this.index) this.manual = true;
        this.select(index, { resetProgress: true });
        if (this.manual) this.stop();
      };
      const onEnter = () => {
        if (index === this.index) this.hoverTab = true;
      };
      const onLeave = () => {
        if (index === this.index) this.hoverTab = false;
      };
      const onKeydown = (event: KeyboardEvent) => this.onKeydown(event, index);

      tab.addEventListener('click', onClick);
      tab.addEventListener('pointerenter', onEnter);
      tab.addEventListener('pointerleave', onLeave);
      tab.addEventListener('keydown', onKeydown);
      this.cleanups.push(() => {
        tab.removeEventListener('click', onClick);
        tab.removeEventListener('pointerenter', onEnter);
        tab.removeEventListener('pointerleave', onLeave);
        tab.removeEventListener('keydown', onKeydown);
      });
    });

    if (this.banner) {
      const banner = this.banner;
      const onEnter = () => {
        this.hoverBanner = true;
      };
      const onLeave = () => {
        this.hoverBanner = false;
      };
      banner.addEventListener('pointerenter', onEnter);
      banner.addEventListener('pointerleave', onLeave);
      this.cleanups.push(() => {
        banner.removeEventListener('pointerenter', onEnter);
        banner.removeEventListener('pointerleave', onLeave);
      });
    }

    this.bindSwipe();
  }

  /** Touch/pen swipe across the banner moves between tabs. */
  private bindSwipe(): void {
    const banner = this.banner;
    if (!banner) return;
    let startX = 0;
    let startY = 0;
    let tracking = false;

    const onDown = (event: PointerEvent) => {
      if (event.pointerType === 'mouse') return;
      tracking = true;
      startX = event.clientX;
      startY = event.clientY;
    };
    const onUp = (event: PointerEvent) => {
      if (!tracking) return;
      tracking = false;
      const dx = event.clientX - startX;
      const dy = event.clientY - startY;
      if (Math.abs(dx) < SWIPE_MIN_PX || Math.abs(dx) < Math.abs(dy) * SWIPE_RATIO) return;
      const next =
        dx < 0
          ? (this.index + 1) % this.tabs.length
          : (this.index - 1 + this.tabs.length) % this.tabs.length;
      this.manual = true;
      this.select(next, { resetProgress: true });
      this.stop();
    };
    const onCancel = () => {
      tracking = false;
    };

    banner.addEventListener('pointerdown', onDown, { passive: true });
    banner.addEventListener('pointerup', onUp, { passive: true });
    banner.addEventListener('pointercancel', onCancel, { passive: true });
    this.cleanups.push(() => {
      banner.removeEventListener('pointerdown', onDown);
      banner.removeEventListener('pointerup', onUp);
      banner.removeEventListener('pointercancel', onCancel);
    });
  }

  private get paused(): boolean {
    return this.hoverTab || PAUSE_ON_HOVER;
  }

  private onKeydown(event: KeyboardEvent, index: number): void {
    const direction = event.key === 'ArrowRight' ? 1 : event.key === 'ArrowLeft' ? -1 : 0;
    if (!direction) return;
    event.preventDefault();
    const next = (index + direction + this.tabs.length) % this.tabs.length;
    this.manual = true;
    this.select(next, { resetProgress: true });
    this.stop();
    this.tabs[next].focus();
  }

  private onVisibility(inView: boolean): void {
    this.inView = inView;
    if (!inView) {
      this.stop();
      this.manual = false;
      return;
    }
    if (!this.manual) this.start();
  }

  select(index: number, { resetProgress = false }: { resetProgress?: boolean } = {}): void {
    this.index = index;
    this.tabs.forEach((tab, i) => {
      const active = i === index;
      tab.setAttribute('aria-selected', active ? 'true' : 'false');
      tab.setAttribute('tabindex', active ? '0' : '-1');
      if (!active) tab.style.setProperty('--tab-progress', '0');
      tab.classList.toggle('is-hovered', active && PAUSE_ON_HOVER);
    });

    this.activeVideo = null;
    this.panels.forEach((panel, i) => {
      const active = i === index;
      panel.classList.toggle('is-active', active);
      const video = panel.querySelector<HTMLVideoElement>('video');
      if (!video) return;
      if (active) this.activeVideo = video;
      players.get(video)?.setSelected(active, { restart: active });
    });

    if (resetProgress) {
      this.elapsed = 0;
      this.lastVideoTime = 0;
      this.setProgress(0);
    }
    this.scrollTabIntoView(index);
  }

  private scrollTabIntoView(index: number): void {
    if (!this.tabList || this.tabList.scrollWidth <= this.tabList.clientWidth) return;
    const tab = this.tabs[index];
    const item = tab.closest('li') || tab;
    this.tabList.scrollTo({
      left: (item as HTMLElement).offsetLeft - this.tabList.offsetLeft - 30,
      behavior: 'smooth',
    });
  }

  private setProgress(value: number): void {
    this.tabs[this.index]?.style.setProperty('--tab-progress', String(value));
  }

  private start(): void {
    if (this.rafId !== null) return;
    this.lastFrame = performance.now();
    this.rafId = requestAnimationFrame(this.tick);
    this.syncFilling();
  }

  private stop(): void {
    if (this.rafId !== null) cancelAnimationFrame(this.rafId);
    this.rafId = null;
    this.syncFilling();
  }

  private syncFilling(): void {
    const filling =
      this.rafId !== null &&
      !this.paused &&
      (!this.activeVideo ||
        (!this.activeVideo.paused && this.activeVideo.readyState >= 2));
    this.root.classList.toggle('is-filling', filling);
  }

  /** A tab lasts as long as its video, or 6s when there is no video. */
  private currentTabDuration(): number {
    const duration = this.activeVideo?.duration;
    return duration && Number.isFinite(duration) && duration > 0
      ? duration * 1000
      : DEFAULT_TAB_MS;
  }

  private tick = (now: number): void => {
    const frameDelta = now - this.lastFrame;
    this.lastFrame = now;

    // A video that looped/seeked backwards restarts the progress bar.
    if (this.activeVideo && this.activeVideo.currentTime < this.lastVideoTime) {
      this.elapsed = 0;
    }

    if (!this.paused) {
      this.elapsed += this.activeVideo
        ? Math.max(
            0,
            (this.activeVideo.currentTime -
              (this.lastVideoTime ?? this.activeVideo.currentTime)) *
              1000,
          )
        : frameDelta;
      const duration = this.currentTabDuration();
      const finished =
        this.elapsed >= duration ||
        this.activeVideo?.ended ||
        (this.activeVideo ? players.get(this.activeVideo)?.completed : false);
      if (finished) {
        this.select((this.index + 1) % this.tabs.length, { resetProgress: true });
      } else {
        this.setProgress(this.elapsed / duration);
      }
    }

    this.lastVideoTime = this.activeVideo?.currentTime ?? 0;
    this.syncFilling();
    this.rafId = requestAnimationFrame(this.tick);
  };

  destroy(): void {
    this.stop();
    this.observer?.disconnect();
    for (const cleanup of this.cleanups) cleanup();
  }
}

export function initVideoPlayers(scope: ParentNode = document): () => void {
  const instances = [...scope.querySelectorAll<HTMLElement>('.video-player')].map(
    (root) => new VideoPlayer(root),
  );
  return () => {
    for (const instance of instances) instance.destroy();
  };
}

export function initTabbedBanners(scope: ParentNode = document): () => void {
  const instances = [...scope.querySelectorAll<HTMLElement>('.tabbed-banner')].map(
    (root) => new TabbedBanner(root),
  );
  return () => {
    for (const instance of instances) instance.destroy();
  };
}

/**
 * Page-level effects ported from scrape/raw/js/intelligence.a7cda79c.js
 * (functions `be` stagger, `Se` visible-video autoplay, `U`/`Re` page-ready) and
 * scrape/raw/js/prefooter.a922aff5.js (class `P` prefooter icons, function `C` card cursor).
 *
 * The reveal helpers here are load-bearing: `.intro__point`, `.features__card` and
 * `.intro .tabbed-banner` are all `opacity:0` in the page's base CSS and only become
 * visible once `is-revealed` / `is-inview` is applied.
 */

const READY_FALLBACK_MS = 1500; // `Re`
const STAGGER_STEP_MS = 300; // `Le`
const PREFOOTER_STEP_MS = 1000; // `k`
const PREFOOTER_IDLE_MS = 4000; // `A`

/** `Ae` — videos owned by another controller must not be auto-played by the generic pass. */
const OWNED_VIDEO_SELECTOR =
  '.hero__propeller-video, [data-play-when-visible], [data-playback-owned]';

const canHover = () => window.matchMedia('(hover: hover) and (pointer: fine)').matches;

/**
 * Adds `is-ready` to <html> once fonts have settled (or after 1500ms regardless), which is
 * what un-gates the page's entry animations. Also mirrors the original's scroll reset.
 */
export function initPageReady(): () => void {
  if ('scrollRestoration' in history) history.scrollRestoration = 'manual';
  window.scrollTo(0, 0);

  const markReady = () => document.documentElement.classList.add('is-ready');
  const fallback = window.setTimeout(markReady, READY_FALLBACK_MS);
  const ready = () => {
    window.clearTimeout(fallback);
    requestAnimationFrame(() => requestAnimationFrame(markReady));
  };

  if (document.fonts) document.fonts.ready.then(ready, ready);
  else ready();

  return () => window.clearTimeout(fallback);
}

/**
 * `be` — reveals the children of every `[data-stagger]` container 300ms apart once the
 * container scrolls into view. `.features__cards` staggers its `.features__card`
 * descendants; anything else staggers its direct children.
 */
export function initStagger(scope: ParentNode = document): () => void {
  const containers = Array.from(scope.querySelectorAll<HTMLElement>('[data-stagger]'));
  if (!containers.length) return () => {};

  const timers: number[] = [];
  const reveal = (container: Element) => {
    const children = container.matches('.features__cards')
      ? Array.from(container.querySelectorAll<HTMLElement>('.features__card'))
      : (Array.from(container.children) as HTMLElement[]);
    children.forEach((child, index) => {
      timers.push(
        window.setTimeout(() => child.classList.add('is-revealed'), index * STAGGER_STEP_MS),
      );
    });
  };

  if (!('IntersectionObserver' in window)) {
    containers.forEach(reveal);
    return () => {
      for (const timer of timers) window.clearTimeout(timer);
    };
  }

  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        reveal(entry.target);
        observer.unobserve(entry.target);
      }
    },
    { threshold: 0, rootMargin: '0px 0px -20% 0px' },
  );
  for (const container of containers) observer.observe(container);

  return () => {
    observer.disconnect();
    for (const timer of timers) window.clearTimeout(timer);
  };
}

/** The trailing block of the original bundle: `.intro .tabbed-banner` gains `is-inview`. */
export function initIntroBannerReveal(scope: ParentNode = document): () => void {
  const banners = Array.from(scope.querySelectorAll<HTMLElement>('.intro .tabbed-banner'));
  if (!banners.length) return () => {};

  if (!('IntersectionObserver' in window)) {
    for (const banner of banners) banner.classList.add('is-inview');
    return () => {};
  }

  const observers = banners.map((banner) => {
    const observer = new IntersectionObserver(
      (entries, self) => {
        for (const entry of entries) {
          if (!entry.isIntersecting) continue;
          entry.target.classList.add('is-inview');
          self.unobserve(entry.target);
        }
      },
      { threshold: 0, rootMargin: '0px 0px -20% 0px' },
    );
    observer.observe(banner);
    return observer;
  });

  return () => {
    for (const observer of observers) observer.disconnect();
  };
}

/**
 * `Se` — plays/pauses any video that no other controller owns as it enters/leaves view.
 * A video is only resumed if it was actually playing when it left.
 */
export function initVisibleVideos(scope: ParentNode = document): () => void {
  const videos = Array.from(scope.querySelectorAll<HTMLVideoElement>('video')).filter(
    (video) => !video.matches(OWNED_VIDEO_SELECTOR),
  );
  if (!videos.length || !('IntersectionObserver' in window)) return () => {};

  const wasPlaying = new WeakMap<Element, boolean>();
  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        const video = entry.target as HTMLVideoElement;
        if (entry.isIntersecting) {
          if (wasPlaying.get(video)) {
            wasPlaying.delete(video);
            video.play().catch(() => {});
          }
        } else {
          const playing = !video.paused && !video.ended;
          wasPlaying.set(video, playing);
          if (playing) video.pause();
        }
      }
    },
    { threshold: 0, rootMargin: '0px 0px -10% 0px' },
  );
  for (const video of videos) observer.observe(video);

  return () => observer.disconnect();
}

/**
 * `C` — the "Find out more" label that follows the pointer across the feature cards.
 * Hover-capable pointers only, so it is inert on touch devices and in screenshots.
 */
export function initCardCursor(container: HTMLElement | null, cardSelector: string): () => void {
  if (!container || !cardSelector) return () => {};
  if (!canHover()) return () => {};

  const cursor = document.createElement('span');
  cursor.className = 'card-cursor';
  cursor.setAttribute('aria-hidden', 'true');
  cursor.textContent = 'Find out more';
  container.append(cursor);

  let zone: HTMLElement | null = null;
  let pointerX = 0;
  let pointerY = 0;

  const place = (x: number, y: number) => {
    const rect = container.getBoundingClientRect();
    cursor.style.setProperty('--card-cursor-x', `${x - rect.left}px`);
    cursor.style.setProperty('--card-cursor-y', `${y - rect.top}px`);
  };
  const track = (event: PointerEvent) => {
    pointerX = event.clientX;
    pointerY = event.clientY;
    place(pointerX, pointerY);
  };
  const reposition = () => {
    if (zone) place(pointerX, pointerY);
  };
  const enter = (card: HTMLElement, event: PointerEvent) => {
    if (zone && zone !== card) zone.classList.remove('is-cursor-zone');
    zone = card;
    card.classList.add('is-cursor-zone');
    track(event);
    requestAnimationFrame(() => cursor.classList.add('is-active'));
  };
  const leave = (card: HTMLElement) => {
    card.classList.remove('is-cursor-zone');
    if (zone === card) zone = null;
    cursor.classList.remove('is-active');
  };

  const onOver = (event: PointerEvent) => {
    const card = (event.target as Element | null)?.closest<HTMLElement>(cardSelector);
    if (!card || !container.contains(card)) return;
    if (card !== zone) enter(card, event);
  };
  const onMove = (event: PointerEvent) => {
    if (zone) track(event);
  };
  const onOut = (event: PointerEvent) => {
    const card = (event.target as Element | null)?.closest<HTMLElement>(cardSelector);
    if (!card) return;
    if (card.contains(event.relatedTarget as Node | null)) return;
    if (card === zone) leave(card);
  };

  container.addEventListener('pointerover', onOver);
  container.addEventListener('pointermove', onMove);
  container.addEventListener('pointerout', onOut);
  window.addEventListener('scroll', reposition, { passive: true, capture: true });

  return () => {
    container.removeEventListener('pointerover', onOver);
    container.removeEventListener('pointermove', onMove);
    container.removeEventListener('pointerout', onOut);
    window.removeEventListener('scroll', reposition, { capture: true });
    cursor.remove();
  };
}

/** Wires a card cursor onto every `.features__cards` group, scoped to its `.features__inner`. */
export function initCardCursors(scope: ParentNode = document): () => void {
  const cleanups = Array.from(scope.querySelectorAll<HTMLElement>('.features__cards')).map(
    (cards) =>
      initCardCursor(
        cards.closest<HTMLElement>('.features__inner') || cards,
        '.features__card',
      ),
  );
  return () => {
    for (const cleanup of cleanups) cleanup();
  };
}

/**
 * `P` — once the prefooter has been in view and idle for 4s, highlight its icons one after
 * another every second. Hovering (or any pointer movement over it) cancels the cycle.
 */
export function initPrefooterIcons(scope: ParentNode = document): () => void {
  const roots = Array.from(scope.querySelectorAll<HTMLElement>('.prefooter'));
  const cleanups: (() => void)[] = [];

  for (const root of roots) {
    const items = Array.from(root.querySelectorAll<HTMLElement>('.prefooter__icons li')).filter(
      (item) => item.querySelector('a'),
    );
    if (!items.length) continue;

    let index = 0;
    let timer: number | null = null;
    let idleTimer: number | null = null;
    let inView = false;
    let hovering = false;

    const clearHighlight = () => {
      for (const item of items) item.classList.remove('is-highlighted');
    };
    const stop = () => {
      if (timer !== null) window.clearTimeout(timer);
      timer = null;
      clearHighlight();
    };
    const clearIdle = () => {
      if (idleTimer !== null) window.clearTimeout(idleTimer);
      idleTimer = null;
    };
    const start = () => {
      if (timer !== null || !inView || hovering) return;
      const step = () => {
        clearHighlight();
        items[index % items.length].classList.add('is-highlighted');
        index += 1;
        timer = window.setTimeout(step, PREFOOTER_STEP_MS);
      };
      step();
    };
    const scheduleIdle = () => {
      clearIdle();
      if (!inView || hovering) return;
      idleTimer = window.setTimeout(start, PREFOOTER_IDLE_MS);
    };

    const itemCleanups: (() => void)[] = [];
    if (canHover()) {
      for (const item of items) {
        const onEnter = () => {
          hovering = true;
          clearIdle();
          stop();
        };
        const onLeave = () => {
          hovering = false;
          scheduleIdle();
        };
        item.addEventListener('pointerenter', onEnter);
        item.addEventListener('pointerleave', onLeave);
        itemCleanups.push(() => {
          item.removeEventListener('pointerenter', onEnter);
          item.removeEventListener('pointerleave', onLeave);
        });
      }
      const onMove = () => {
        if (hovering) return;
        stop();
        scheduleIdle();
      };
      root.addEventListener('pointermove', onMove);
      itemCleanups.push(() => root.removeEventListener('pointermove', onMove));
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        inView = entry.isIntersecting;
        if (inView) scheduleIdle();
        else stop();
      },
      { threshold: 0.4 },
    );
    observer.observe(root);

    cleanups.push(() => {
      observer.disconnect();
      clearIdle();
      stop();
      for (const cleanup of itemCleanups) cleanup();
    });
  }

  return () => {
    for (const cleanup of cleanups) cleanup();
  };
}

/**
 * Minimal ambient types for the packaged Flickity build.
 *
 * The live page bundles its own copy of Flickity inline inside disclaimer.js; we install the
 * matching v2 release from npm instead (v2.3.0 — same `.flickity-enabled`/`.flickity-viewport`/
 * `.flickity-page-dots` class names the captured CSS already styles). Only the surface the
 * page's own carousel controllers actually use is declared here.
 */
declare module 'flickity/dist/flickity.pkgd.js' {
  export interface FlickityOptions {
    pageDots?: boolean;
    prevNextButtons?: boolean;
    draggable?: boolean;
    dragThreshold?: number;
    autoPlay?: boolean | number;
    cellAlign?: 'left' | 'center' | 'right';
    contain?: boolean;
    imagesLoaded?: boolean;
    initialIndex?: number;
    groupCells?: boolean | number | string;
    [option: string]: unknown;
  }

  export default class Flickity {
    constructor(element: Element | string, options?: FlickityOptions);
    selectedIndex: number;
    isAnimating: boolean;
    destroy(): void;
    append(element: Element): void;
    remove(element: Element): void;
    next(isWrap?: boolean): void;
    previous(isWrap?: boolean): void;
    resize(): void;
  }
}

/**
 * Flickity-backed carousels, ported from scrape/raw/js/intelligence.a7cda79c.js
 * (minified class `ge` = the discover carousel, class `_e` = the feature/trust card
 * carousels) plus the horizontal wheel-drag helper `te` from disclaimer.js.
 *
 * Note the asymmetry, straight from the source:
 *   - `.discover__track` is a Flickity carousel at *every* width — only its options change
 *     across the breakpoint (desktop centres and un-contains its cells), so this is
 *     layout-affecting on desktop too, not just a mobile nicety;
 *   - `.features__cards` / `.trust__cards` are only Flickity below 768px and fall back to
 *     the CSS grid above it.
 *
 * Flickity is loaded dynamically so it never runs during SSR.
 */

import type Flickity from 'flickity/dist/flickity.pkgd.js';
import type { FlickityOptions } from 'flickity/dist/flickity.pkgd.js';

/** `Ee` / `Te` — both controllers use the same breakpoint. */
const MOBILE_QUERY = '(max-width: 767.98px)';
/** `Gt` / `jt` — horizontal wheel accumulation before advancing, and the reset debounce. */
const WHEEL_STEP_PX = 40;
const WHEEL_RESET_MS = 140;
/** The card carousels re-sync on a debounced resize. */
const RESIZE_DEBOUNCE_MS = 150;
/** Trailing spacer so the last cell can scroll clear of the viewport edge on mobile. */
const SPACER_WIDTH = '40px';

type FlickityCtor = typeof Flickity;
type FlickityInstance = Flickity;

let loader: Promise<FlickityCtor> | null = null;

function loadFlickity(): Promise<FlickityCtor> {
  if (!loader) {
    loader = import('flickity/dist/flickity.pkgd.js').then(
      (module) => (module.default ?? module) as FlickityCtor,
    );
  }
  return loader;
}

function makeSpacer(): HTMLElement {
  const spacer = document.createElement('div');
  spacer.className = 'carousel-spacer';
  spacer.setAttribute('aria-hidden', 'true');
  spacer.style.width = SPACER_WIDTH;
  return spacer;
}

/**
 * `te` — lets a horizontal wheel/trackpad gesture drive the carousel, swallowing the event
 * so the page does not scroll sideways instead.
 */
function bindWheelDrag(instance: FlickityInstance, track: HTMLElement): () => void {
  let accumulated = 0;
  let advanced = false;
  let resetTimer: number | null = null;

  const reset = () => {
    accumulated = 0;
    advanced = false;
  };

  const onWheel = (event: WheelEvent) => {
    if (Math.abs(event.deltaX) <= Math.abs(event.deltaY)) return;
    if (instance.isAnimating) return;
    event.preventDefault();
    if (resetTimer !== null) window.clearTimeout(resetTimer);
    resetTimer = window.setTimeout(reset, WHEEL_RESET_MS);
    if (advanced) return;
    accumulated += event.deltaX;
    if (Math.abs(accumulated) < WHEEL_STEP_PX) return;
    if (accumulated > 0) instance.next();
    else instance.previous();
    advanced = true;
    accumulated = 0;
  };

  track.addEventListener('wheel', onWheel, { passive: false });
  return () => {
    if (resetTimer !== null) window.clearTimeout(resetTimer);
    track.removeEventListener('wheel', onWheel);
  };
}

/** `ge` — the discover carousel: always on, rebuilt when the breakpoint flips. */
class DiscoverCarousel {
  private readonly track: HTMLElement | null;
  private readonly mobile: MediaQueryList | null = null;
  private readonly onBreakpoint: () => void;

  private instance: FlickityInstance | null = null;
  private spacer: HTMLElement | null = null;
  private unbindWheel: (() => void) | null = null;
  private destroyed = false;

  constructor(block: HTMLElement) {
    this.track = block.querySelector<HTMLElement>('.discover__track');
    this.onBreakpoint = () => {
      this.syncSpacer();
      void this.build();
    };
    if (!this.track) return;
    this.mobile = window.matchMedia(MOBILE_QUERY);
    this.mobile.addEventListener('change', this.onBreakpoint);
    this.syncSpacer();
    void this.build();
  }

  /** Desktop centres the cells and lets them overflow; mobile left-aligns and contains them. */
  private options(): FlickityOptions {
    const desktop = !this.mobile!.matches;
    return {
      pageDots: true,
      prevNextButtons: false,
      draggable: true,
      dragThreshold: 30,
      autoPlay: false,
      cellAlign: desktop ? 'center' : 'left',
      contain: !desktop,
      imagesLoaded: true,
    };
  }

  private async build(): Promise<void> {
    if (!this.track) return;
    const Ctor = await loadFlickity();
    if (this.destroyed || !this.track) return;

    const initialIndex = this.instance ? this.instance.selectedIndex : 0;
    this.teardownInstance();

    this.instance = new Ctor(this.track, { ...this.options(), initialIndex });
    this.unbindWheel = bindWheelDrag(this.instance, this.track);
  }

  private teardownInstance(): void {
    this.unbindWheel?.();
    this.unbindWheel = null;
    this.instance?.destroy();
    this.instance = null;
  }

  /** The spacer is a real cell once Flickity owns the track, so it must be added via the API. */
  private syncSpacer(): void {
    if (!this.track || !this.mobile) return;
    if (this.mobile.matches) {
      if (this.spacer) return;
      this.spacer = makeSpacer();
      if (this.instance) this.instance.append(this.spacer);
      else this.track.appendChild(this.spacer);
      this.track.classList.add('has-carousel-spacer');
    } else {
      if (!this.spacer) return;
      if (this.instance) this.instance.remove(this.spacer);
      else this.spacer.remove();
      this.spacer = null;
      this.track.classList.remove('has-carousel-spacer');
    }
  }

  destroy(): void {
    this.destroyed = true;
    this.mobile?.removeEventListener('change', this.onBreakpoint);
    this.teardownInstance();
    this.spacer?.remove();
    this.spacer = null;
    this.track?.classList.remove('has-carousel-spacer');
  }
}

/** `_e` — feature/trust card tracks: Flickity below 768px only, CSS grid above it. */
class CardCarousel {
  private readonly track: HTMLElement;
  private readonly mobile: MediaQueryList;
  private readonly onChange: () => void;
  private readonly onResize: () => void;

  private instance: FlickityInstance | null = null;
  private spacer: HTMLElement | null = null;
  private unbindWheel: (() => void) | null = null;
  private resizeTimer: number | null = null;
  private destroyed = false;
  private building = false;

  constructor(track: HTMLElement) {
    this.track = track;
    this.mobile = window.matchMedia(MOBILE_QUERY);
    this.onChange = () => void this.sync();
    this.onResize = () => {
      if (this.resizeTimer !== null) window.clearTimeout(this.resizeTimer);
      this.resizeTimer = window.setTimeout(() => void this.sync(), RESIZE_DEBOUNCE_MS);
    };
    this.mobile.addEventListener('change', this.onChange);
    window.addEventListener('resize', this.onResize, { passive: true });
    void this.sync();
  }

  private async sync(): Promise<void> {
    if (this.destroyed) return;
    if (this.mobile.matches) await this.enable();
    else this.disable();
  }

  private async enable(): Promise<void> {
    if (this.instance || this.building) return;
    this.building = true;
    try {
      const Ctor = await loadFlickity();
      // The breakpoint may have flipped back while the chunk was loading.
      if (this.destroyed || this.instance || !this.mobile.matches) return;

      this.spacer = makeSpacer();
      this.track.appendChild(this.spacer);
      this.track.classList.add('has-carousel-spacer');

      this.instance = new Ctor(this.track, {
        pageDots: true,
        prevNextButtons: false,
        draggable: true,
        dragThreshold: 30,
        autoPlay: false,
        cellAlign: 'left',
        contain: true,
        imagesLoaded: true,
        initialIndex: 0,
        groupCells: false,
      });
      this.unbindWheel = bindWheelDrag(this.instance, this.track);
    } finally {
      this.building = false;
    }
  }

  private disable(): void {
    if (!this.instance) return;
    this.unbindWheel?.();
    this.unbindWheel = null;
    this.instance.destroy();
    this.instance = null;
    this.spacer?.remove();
    this.spacer = null;
    this.track.classList.remove('has-carousel-spacer');
  }

  destroy(): void {
    this.destroyed = true;
    this.mobile.removeEventListener('change', this.onChange);
    window.removeEventListener('resize', this.onResize);
    if (this.resizeTimer !== null) window.clearTimeout(this.resizeTimer);
    this.disable();
  }
}

export function initDiscoverCarousels(scope: ParentNode = document): () => void {
  const instances = [...scope.querySelectorAll<HTMLElement>('.discover')].map(
    (block) => new DiscoverCarousel(block),
  );
  return () => {
    for (const instance of instances) instance.destroy();
  };
}

export function initCardCarousels(scope: ParentNode = document): () => void {
  const instances = [
    ...scope.querySelectorAll<HTMLElement>('.features__cards, .trust__cards'),
  ].map((track) => new CardCarousel(track));
  return () => {
    for (const instance of instances) instance.destroy();
  };
}

