#!/usr/bin/env node
/**
 * Throwaway follow-up probe (gitignored scrape/ dir).
 *
 * probe-live-hidden.mjs established that `ul.MCountrySelector-options-*` is
 * hidden on LIVE by a structurally-hidden ANCESTOR (0x0, onScreen=false,
 * structurallyHidden=true) but is on-screen and 182x165 locally with only
 * opacity:0 -- so this is a real local divergence, not a live-site quirk to
 * baseline.
 *
 * This dumps the full ancestor chain of that <ul> on both targets at one mobile
 * viewport so the exact differing node and property can be diffed directly.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const TARGETS = [
  ['live ', 'https://www.intuit.com/intuit-intelligence/'],
  ['local', 'http://localhost:3308/'],
];

const MOBILE_UA =
  'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 ' +
  '(KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';

/** Runs in the page. Must not close over anything from this module. */
function chain() {
  const el = document.querySelector('ul[class*="MCountrySelector-options"]');
  if (!el) return { found: false, rows: [] };

  const rows = [];
  for (let n = el; n && n !== document.documentElement.parentElement; n = n.parentElement) {
    const s = getComputedStyle(n);
    const r = n.getBoundingClientRect();
    rows.push({
      tag: n.tagName.toLowerCase(),
      cls: String(n.className || '').slice(0, 64),
      id: n.id || '',
      inline: (n.getAttribute('style') || '').slice(0, 90),
      display: s.display,
      visibility: s.visibility,
      opacity: s.opacity,
      overflow: `${s.overflowX}/${s.overflowY}`,
      height: s.height,
      maxHeight: s.maxHeight,
      transform: s.transform === 'none' ? 'none' : s.transform.slice(0, 40),
      pointerEvents: s.pointerEvents,
      ariaHidden: n.getAttribute('aria-hidden'),
      hiddenAttr: n.hasAttribute('hidden'),
      box: `${Math.round(r.width)}x${Math.round(r.height)}`,
      hides: s.display === 'none' || s.visibility === 'hidden' || n.getAttribute('aria-hidden') === 'true',
    });
  }
  return { found: true, rows };
}

const browser = await launch(chromium, { headless: true });

for (const [label, url] of TARGETS) {
  const ctx = await browser.newContext({
    viewport: { width: 375, height: 667 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: MOBILE_UA,
  });
  const page = await ctx.newPage();
  try {
    await page.goto(url, { waitUntil: 'load', timeout: 90000 });
    await page.waitForTimeout(3500);
    const res = await page.evaluate(chain);
    console.log(`\n=================== ${label} (375x667) ===================`);
    if (!res.found) {
      console.log('  <ul> not present');
    }
    for (const [i, r] of res.rows.entries()) {
      console.log(
        `${String(i).padStart(2)} ${r.hides ? '>>HIDES<<' : '         '} ${r.tag}` +
          `${r.id ? '#' + r.id : ''} .${r.cls}`,
      );
      console.log(
        `    display=${r.display} vis=${r.visibility} opacity=${r.opacity} ` +
          `box=${r.box} h=${r.height} maxH=${r.maxHeight}`,
      );
      console.log(
        `    overflow=${r.overflow} transform=${r.transform} pe=${r.pointerEvents} ` +
          `aria-hidden=${r.ariaHidden} hidden=${r.hiddenAttr}`,
      );
      if (r.inline) console.log(`    inline-style="${r.inline}"`);
    }
  } catch (err) {
    console.log(`\n=== ${label} FAILED: ${err.message}`);
  } finally {
    await ctx.close();
  }
}

await browser.close();

#!/usr/bin/env node
/**
 * Throwaway probe (gitignored scrape/ dir).
 *
 * Question: does the CAPTURED css contain any rule that hides the desktop-only
 * global-nav pieces at phone widths, and if so why is it not winning?
 *
 * Context: the captured DOM is Intuit's global nav as rendered at DESKTOP width
 * (live re-renders a different nav client-side per breakpoint -- live's mobile
 * DOM has no S01MegaNav-left-wrapper at all). So at 375px the replica keeps
 * showing desktop nav markup, leaving ul.MCountrySelector-options on screen at
 * opacity 0 (the gate's hidden-content failure).
 *
 * This enumerates every CSS rule matching the nav/country-selector elements,
 * with its enclosing @media condition, so it is clear whether the media query
 * exists in the captured CSS, is missing entirely, or is being beaten.
 *
 * Note: live's stylesheets may be cross-origin and therefore unreadable
 * (cssRules throws); the LOCAL side is the one that matters here.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const TARGETS = [
  ['local', 'http://localhost:3308/'],
  ['live ', 'https://www.intuit.com/intuit-intelligence/'],
];

const MOBILE_UA =
  'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 ' +
  '(KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1';

/** Runs in the page. Must not close over anything from this module. */
function cssFor() {
  const SELECTORS = [
    'ul[class*="MCountrySelector-options"]',
    '[class*="MCountrySelector-m-country-selector"]',
    '[class*="MCountrySelector-desktop"]',
    '[class*="MCountrySelector-mobile"]',
    '[class*="S01MegaNav-left-wrapper"]',
    '[class*="S01MegaNav-links-list"]',
    '[class*="S01MegaNav-mobile"]',
  ];

  const els = [];
  for (const sel of SELECTORS) {
    const e = document.querySelector(sel);
    if (e) els.push([sel, e]);
  }

  const out = [];
  const INTERESTING = /(^|;|\s)(display|visibility|opacity|max-height|transform)\s*:/;

  const visit = (rules, cond) => {
    for (const rule of rules) {
      // @media / @supports / @layer wrappers: recurse, carrying the condition.
      if (rule.conditionText !== undefined && rule.cssRules) {
        visit(rule.cssRules, (cond ? cond + ' && ' : '') + rule.conditionText);
        continue;
      }
      if (rule.cssRules && rule.selectorText === undefined) {
        visit(rule.cssRules, cond);
        continue;
      }
      if (!rule.selectorText) continue;

      const css = rule.style ? rule.style.cssText : '';
      if (!INTERESTING.test(css)) continue;

      for (const [sel, e] of els) {
        let hit = false;
        try {
          hit = e.matches(rule.selectorText);
        } catch {
          hit = false;
        }
        if (!hit) continue;
        out.push({
          sel,
          cond: cond || '(no media)',
          rule: rule.selectorText.slice(0, 90),
          css: css.slice(0, 170),
        });
      }
    }
  };

  let unreadable = 0;
  for (const ss of document.styleSheets) {
    try {
      visit(ss.cssRules, '');
    } catch {
      unreadable += 1;
    }
  }

  return { present: els.map(([s]) => s), unreadable, out };
}

const browser = await launch(chromium, { headless: true });

for (const [label, url] of TARGETS) {
  const ctx = await browser.newContext({
    viewport: { width: 375, height: 667 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: MOBILE_UA,
  });
  const page = await ctx.newPage();
  try {
    await page.goto(url, { waitUntil: 'load', timeout: 90000 });
    await page.waitForTimeout(3500);
    const res = await page.evaluate(cssFor);
    console.log(`\n=================== ${label} (375x667) ===================`);
    console.log(`  elements present: ${res.present.join('  ') || '(none)'}`);
    console.log(`  unreadable stylesheets (cross-origin): ${res.unreadable}`);
    for (const r of res.out) {
      console.log(`\n  [${r.cond}]`);
      console.log(`    for ${r.sel}`);
      console.log(`    ${r.rule}`);
      console.log(`      { ${r.css} }`);
    }
  } catch (err) {
    console.log(`\n=== ${label} FAILED: ${err.message}`);
  } finally {
    await ctx.close();
  }
}

await browser.close();

#!/usr/bin/env node
/**
 * Throwaway probe (gitignored scrape/ dir).
 *
 * Mystery to settle: ul.MCountrySelector-options-* computes to opacity 0 in the
 * replica, but enumerating document.styleSheets found NO rule that sets opacity
 * on it -- and none inside any @media block either (the enumerator walked into
 * media blocks regardless of whether they currently matched). So the
 * transparency comes from somewhere a naive declaration scan cannot see: an
 * `animation` whose keyframes end at 0, a shorthand, or an inline/UA path.
 *
 * It also has to explain an asymmetry: the viewport gate reports this block as
 * hidden-content ONLY below 768px (iphone-se / iphone-14-pro / pixel-7) and
 * never on ipad-mini(768) / ipad-pro / laptop / desktop-wide.
 *
 * CDP's CSS.getMatchedStylesForNode answers both precisely: it returns every
 * matched rule in cascade order with its media conditions, plus inline styles
 * and the keyframes backing any animation.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const URL = 'http://localhost:3308/';
const SEL = 'ul[class*="MCountrySelector-options"]';

/** [width, height, dpr, isMobile] -- straddling the 768 boundary. */
const VIEWPORTS = [
  [375, 667, 2, true],
  [768, 1024, 2, true],
  [1440, 900, 1, false],
];

const RELEVANT = /(opacity|visibility|display|animation|transition|transform|max-height|height|pointer-events|position|top)/;

const browser = await launch(chromium, { headless: true });

for (const [w, h, dpr, isMobile] of VIEWPORTS) {
  const ctx = await browser.newContext({
    viewport: { width: w, height: h },
    deviceScaleFactor: dpr,
    isMobile,
    hasTouch: isMobile,
  });
  const page = await ctx.newPage();
  console.log(`\n================== local ${w}x${h} ==================`);
  try {
    await page.goto(URL, { waitUntil: 'load', timeout: 90000 });
    await page.waitForTimeout(3000);

    const computed = await page.evaluate((sel) => {
      const e = document.querySelector(sel);
      if (!e) return null;
      const s = getComputedStyle(e);
      const r = e.getBoundingClientRect();
      // Does an ancestor hide it structurally (what the gate excludes on)?
      let hiddenBy = null;
      for (let n = e; n && n !== document.documentElement; n = n.parentElement) {
        const cs = getComputedStyle(n);
        if (cs.display === 'none' || cs.visibility === 'hidden' || n.getAttribute('aria-hidden') === 'true') {
          hiddenBy = `${n.tagName.toLowerCase()}.${String(n.className).split(' ')[0]}`;
          break;
        }
      }
      return {
        opacity: s.opacity,
        visibility: s.visibility,
        display: s.display,
        animationName: s.animationName,
        animationFillMode: s.animationFillMode,
        animationPlayState: s.animationPlayState,
        transition: s.transitionProperty,
        box: `${Math.round(r.width)}x${Math.round(r.height)}`,
        top: Math.round(r.top),
        onScreen: r.top < window.innerHeight && r.bottom > 0 && r.width > 0 && r.height > 0,
        hiddenBy,
        inline: e.getAttribute('style'),
      };
    }, SEL);

    console.log(`  computed: ${JSON.stringify(computed, null, 0)}`);
    if (!computed) {
      await ctx.close();
      continue;
    }

    const cdp = await ctx.newCDPSession(page);
    await cdp.send('DOM.enable');
    await cdp.send('CSS.enable');
    const { root } = await cdp.send('DOM.getDocument', { depth: -1 });
    const { nodeId } = await cdp.send('DOM.querySelector', { nodeId: root.nodeId, selector: SEL });
    if (!nodeId) {
      console.log('  CDP could not resolve the node');
      await ctx.close();
      continue;
    }

    const ms = await cdp.send('CSS.getMatchedStylesForNode', { nodeId });

    if (ms.inlineStyle?.cssText) {
      console.log(`\n  INLINE: ${ms.inlineStyle.cssText.replace(/\s+/g, ' ').trim()}`);
    }
    if (ms.attributesStyle?.cssText) {
      console.log(`  PRESENTATION-ATTR: ${ms.attributesStyle.cssText.replace(/\s+/g, ' ').trim()}`);
    }

    console.log('\n  --- matched rules (cascade order, visibility-relevant only) ---');
    for (const m of ms.matchedCSSRules ?? []) {
      const r = m.rule;
      const decls = (r.style?.cssText ?? '').replace(/\s+/g, ' ').trim();
      if (!RELEVANT.test(decls)) continue;
      const media = (r.media ?? []).map((x) => x.text).join(' && ');
      const origin = r.origin !== 'regular' ? ` <${r.origin}>` : '';
      console.log(`  [${media || 'no media'}]${origin} ${(r.selectorList?.text ?? '').slice(0, 100)}`);
      console.log(`      ${decls.slice(0, 220)}`);
    }

    const kf = ms.cssKeyframesRules ?? [];
    if (kf.length) {
      console.log('\n  --- keyframes referenced by this node ---');
      for (const k of kf) {
        console.log(`  @keyframes ${k.animationName?.text}`);
        for (const f of k.keyframes ?? []) {
          console.log(`      ${f.keyText?.text}  { ${(f.style?.cssText ?? '').replace(/\s+/g, ' ').trim().slice(0, 120)} }`);
        }
      }
    }
  } catch (err) {
    console.log(`  FAILED: ${err.message}`);
  } finally {
    await ctx.close();
  }
}

await browser.close();

