#!/usr/bin/env node
/**
 * Throwaway probe (gitignored scrape/ dir).
 *
 * Finding to explain: compare-live's desktop-wide slice at y=1080 is 8.72% on
 * the way DOWN but 35.08% on the way UP, and the composite shows the replica
 * painting an empty grey rounded rectangle where live paints the black
 * laptop/video mockup in the "AI that understands your finances" section.
 * Surrounding copy and the TurboTax/Credit Karma/Mailchimp/QuickBooks tabs match
 * exactly, so this is not a layout or copy difference -- a media element is
 * simply not painted on the second visit.
 *
 * Hypothesis worth testing: intuitVideo's PlaybackManager/TabbedBanner starts
 * playback from an IntersectionObserver, and on the way back up either the
 * observer never re-fires or syncSource re-points video.src and the reload never
 * produces a frame (these videos carry no poster, so an unloaded <video> paints
 * as an empty box rather than a first frame).
 *
 * So: walk down the page exactly like the sweep does, sample every <video>,
 * walk back up to the same offset, and sample again. A video with
 * readyState 0 / videoWidth 0 only on the upward pass confirms it.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const URL = 'http://localhost:3308/';
const WIDTH = 1920;
const HEIGHT = 1080;
const TARGET_Y = 1080; // the disputed slice

/** Runs in the page. Must not close over anything from this module. */
function sampleVideos() {
  const rows = [];
  for (const v of Array.from(document.querySelectorAll('video'))) {
    const r = v.getBoundingClientRect();
    const onScreen = r.top < window.innerHeight && r.bottom > 0 && r.width > 0 && r.height > 0;
    if (!onScreen) continue;
    const s = getComputedStyle(v);
    rows.push({
      src: (v.currentSrc || v.getAttribute('src') || '(none)').split('/').pop().slice(0, 52),
      readyState: v.readyState,
      networkState: v.networkState,
      paused: v.paused,
      currentTime: Number(v.currentTime.toFixed(2)),
      vw: v.videoWidth,
      vh: v.videoHeight,
      poster: v.getAttribute('poster') ? 'yes' : 'no',
      preload: v.getAttribute('preload') || '(default)',
      sources: v.querySelectorAll('source').length,
      box: `${Math.round(r.width)}x${Math.round(r.height)}`,
      top: Math.round(r.top),
      opacity: s.opacity,
      visibility: s.visibility,
    });
  }
  return rows;
}

const show = (label, rows) => {
  console.log(`\n--- ${label} (${rows.length} video(s) on screen) ---`);
  for (const v of rows) {
    console.log(
      `  readyState=${v.readyState} netState=${v.networkState} paused=${v.paused} ` +
        `t=${v.currentTime} frame=${v.vw}x${v.vh} box=${v.box} top=${v.top} ` +
        `opacity=${v.opacity} poster=${v.poster} preload=${v.preload} sources=${v.sources}`,
    );
    console.log(`      ${v.src}`);
  }
  if (!rows.length) console.log('  (none)');
};

const browser = await launch(chromium, { headless: true });
const ctx = await browser.newContext({
  viewport: { width: WIDTH, height: HEIGHT },
  deviceScaleFactor: 1,
});
const page = await ctx.newPage();

await page.goto(URL, { waitUntil: 'load', timeout: 90000 });
await page.waitForTimeout(3500);

const pageHeight = await page.evaluate(() => document.documentElement.scrollHeight);
console.log(`page height ${pageHeight}, viewport ${WIDTH}x${HEIGHT}, target slice y=${TARGET_Y}`);

// ---- downward pass, sampling at the disputed offset ----------------------
for (let y = 0; y <= pageHeight - HEIGHT; y += HEIGHT) {
  await page.evaluate((to) => window.scrollTo(0, to), y);
  await page.waitForTimeout(500);
  if (y === TARGET_Y) show(`DOWN  y=${y}`, await page.evaluate(sampleVideos));
}

// ---- reach the bottom, then walk back up --------------------------------
await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
await page.waitForTimeout(800);

for (let y = pageHeight - HEIGHT; y >= 0; y -= HEIGHT) {
  await page.evaluate((to) => window.scrollTo(0, to), y);
  await page.waitForTimeout(500);
  if (y === TARGET_Y) show(`UP    y=${y}`, await page.evaluate(sampleVideos));
}

// A second downward visit distinguishes "only ever works once" from
// "only works in the downward direction".
for (let y = 0; y <= pageHeight - HEIGHT; y += HEIGHT) {
  await page.evaluate((to) => window.scrollTo(0, to), y);
  await page.waitForTimeout(500);
  if (y === TARGET_Y) show(`DOWN AGAIN y=${y}`, await page.evaluate(sampleVideos));
}

await ctx.close();
await browser.close();

