#!/usr/bin/env node
/**
 * Throwaway probe (gitignored scrape/ dir).
 *
 * The iphone-se compare slice at y=7271 (66.9% diff) shows the discover carousel
 * rendering differently on each side at 375px:
 *   - LOCAL: cell flush to the left edge, next cell visibly peeking in at the right;
 *   - LIVE : cell inset/centred with no peek, three page dots below.
 *
 * Both carousels are ported with autoPlay:false, so this CANNOT be a "two
 * unsynchronised autoplay clocks" difference the way the hero video was -- both
 * sides should be sitting still at initialIndex 0. So either
 *   (a) our cellAlign/contain ternary is inverted vs live (real bug), or
 *   (b) live isn't Flickity-driven at this width at all, or
 *   (c) the cells themselves are sized differently by CSS.
 *
 * Measure, don't guess: report the track, its flickity viewport, the slider
 * transform, which cell is selected, and every cell's rect on both sides.
 * Also check for horizontal document overflow, the classic mobile symptom of a
 * carousel whose cells are not contained.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const TARGETS = [
  ['live ', 'https://www.intuit.com/intuit-intelligence/'],
  ['local', 'http://localhost:3308/'],
];

const VIEWPORTS = [
  ['mobile  375x667', { width: 375, height: 667 }],
  ['desktop 1440x900', { width: 1440, height: 900 }],
];

/** Runs in the page. Must not close over anything from this module. */
function measure() {
  const rect = (el) => {
    const r = el.getBoundingClientRect();
    return {
      left: Math.round(r.left),
      right: Math.round(r.right),
      width: Math.round(r.width),
      height: Math.round(r.height),
    };
  };

  const describeTrack = (track) => {
    const s = getComputedStyle(track);
    const viewport = track.querySelector('.flickity-viewport');
    const slider = track.querySelector('.flickity-slider');
    const dots = track.querySelector('.flickity-page-dots');

    // Flickity moves the original children under .flickity-slider once enabled.
    const cellParent = slider || track;
    const cells = Array.from(cellParent.children)
      .filter((c) => !c.classList.contains('flickity-page-dots'))
      .slice(0, 6)
      .map((c) => ({
        cls: String(c.className || '').slice(0, 70),
        selected: c.classList.contains('is-selected'),
        rect: rect(c),
        marginLeft: getComputedStyle(c).marginLeft,
        widthStyle: getComputedStyle(c).width,
      }));

    return {
      cls: String(track.className || '').slice(0, 90),
      flickityEnabled: track.classList.contains('flickity-enabled'),
      overflow: `${s.overflowX}/${s.overflowY}`,
      padding: s.padding,
      rect: rect(track),
      viewportRect: viewport ? rect(viewport) : null,
      sliderTransform: slider ? getComputedStyle(slider).transform : null,
      sliderRect: slider ? rect(slider) : null,
      dotCount: dots ? dots.querySelectorAll('.dot').length : null,
      selectedDot: dots
        ? Array.from(dots.querySelectorAll('.dot')).findIndex((d) =>
            d.classList.contains('is-selected'),
          )
        : null,
      cellCount: cellParent.children.length,
      cells,
    };
  };

  const out = { tracks: {}, overflow: {} };
  for (const sel of ['.discover__track', '.features__cards', '.trust__cards']) {
    const el = document.querySelector(sel);
    out.tracks[sel] = el ? describeTrack(el) : null;
  }

  out.overflow = {
    innerWidth: window.innerWidth,
    docScrollWidth: document.documentElement.scrollWidth,
    bodyScrollWidth: document.body.scrollWidth,
    horizontallyScrollable: document.documentElement.scrollWidth > window.innerWidth + 1,
  };
  return out;
}

const report = (m) => {
  const o = m.overflow;
  console.log(
    `  innerWidth=${o.innerWidth} docScrollWidth=${o.docScrollWidth} ` +
      `bodyScrollWidth=${o.bodyScrollWidth} hOverflow=${o.horizontallyScrollable}`,
  );
  for (const [sel, t] of Object.entries(m.tracks)) {
    if (!t) {
      console.log(`  ${sel}: (absent)`);
      continue;
    }
    console.log(`  ${sel}:`);
    console.log(
      `      flickityEnabled=${t.flickityEnabled} overflow=${t.overflow} padding=${t.padding}`,
    );
    console.log(`      class="${t.cls}"`);
    console.log(
      `      track   ${JSON.stringify(t.rect)}  viewport ${JSON.stringify(t.viewportRect)}`,
    );
    console.log(`      slider  transform=${t.sliderTransform} rect=${JSON.stringify(t.sliderRect)}`);
    console.log(`      dots    count=${t.dotCount} selected=${t.selectedDot} cells=${t.cellCount}`);
    t.cells.forEach((c, i) => {
      console.log(
        `      cell[${i}] sel=${c.selected} w=${c.widthStyle} ml=${c.marginLeft} ` +
          `${JSON.stringify(c.rect)} class="${c.cls}"`,
      );
    });
  }
};

const browser = await launch(chromium, { headless: true });

for (const [vpLabel, viewport] of VIEWPORTS) {
  for (const [label, url] of TARGETS) {
    const isMobile = viewport.width < 500;
    const ctx = await browser.newContext({
      viewport,
      deviceScaleFactor: isMobile ? 2 : 1,
      isMobile,
      hasTouch: isMobile,
    });
    const page = await ctx.newPage();
    try {
      await page.goto(url, { waitUntil: 'load', timeout: 90000 });
      await page.waitForTimeout(3500);
      // Bring the carousel into view: lazy/Flickity layout can depend on it.
      await page.evaluate(() => {
        const el = document.querySelector('.discover__track');
        if (el) el.scrollIntoView({ block: 'center' });
      });
      await page.waitForTimeout(1200);
      console.log(`\n=========== ${label} @ ${vpLabel} ===========`);
      report(await page.evaluate(measure));
    } catch (err) {
      console.log(`\n=========== ${label} @ ${vpLabel} FAILED: ${err.message}`);
    } finally {
      await ctx.close();
    }
  }
}

await browser.close();

#!/usr/bin/env node
/**
 * Throwaway probe (gitignored scrape/ dir).
 *
 * After the Flickity v3 fix every viewport's total document height matches live
 * EXACTLY (iphone-se 10015/10015, laptop 10109/10109, ...). Yet the iphone-se
 * slice at y=9348 shows the footer's brand links sitting ~51px higher locally
 * than on live. Equal totals + a local offset near the bottom means something
 * above the footer is ~51px TALLER locally and the footer itself ~51px shorter
 * (or vice versa) -- the two cancelling out in the total.
 *
 * So: map the whole page vertically on both sides and diff it. Print every
 * visible block down to depth 2 with its absolute offsetTop and height, so the
 * first row whose top diverges pinpoints exactly which section drifts.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const TARGETS = [
  ['live', 'https://www.intuit.com/intuit-intelligence/'],
  ['local', 'http://localhost:3308/'],
];

const VIEWPORT = { width: 375, height: 667 };

/** Runs in the page. Must not close over anything from this module. */
function measure() {
  const label = (el) => {
    const cls =
      typeof el.className === 'string' && el.className.trim()
        ? '.' + el.className.trim().split(/\s+/).slice(0, 2).join('.')
        : '';
    return `${el.tagName.toLowerCase()}${el.id ? '#' + el.id : ''}${cls}`;
  };

  const nodes = [];
  const walk = (el, depth) => {
    for (const child of el.children) {
      if (!(child instanceof HTMLElement)) continue;
      const style = getComputedStyle(child);
      if (style.display === 'none' || style.position === 'fixed') continue;
      const height = child.offsetHeight;
      if (height > 4) {
        const rect = child.getBoundingClientRect();
        nodes.push({
          depth,
          sel: label(child).slice(0, 52),
          top: Math.round(rect.top + window.scrollY),
          h: height,
        });
      }
      if (depth < 2) walk(child, depth + 1);
    }
  };
  walk(document.body, 0);

  return { scrollHeight: document.documentElement.scrollHeight, nodes };
}

const results = {};
const browser = await launch(chromium, { headless: true });

for (const [key, url] of TARGETS) {
  const ctx = await browser.newContext({
    viewport: VIEWPORT,
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
  });
  const page = await ctx.newPage();
  try {
    await page.goto(url, { waitUntil: 'load', timeout: 90000 });
    await page.waitForTimeout(3500);
    // Scroll the whole page so lazy/reveal content has laid out, then return to 0.
    await page.evaluate(async () => {
      const step = window.innerHeight;
      for (let y = 0; y < document.documentElement.scrollHeight; y += step) {
        window.scrollTo(0, y);
        await new Promise((r) => setTimeout(r, 60));
      }
      window.scrollTo(0, 0);
    });
    await page.waitForTimeout(1200);
    results[key] = await page.evaluate(measure);
  } catch (err) {
    console.log(`${key} FAILED: ${err.message}`);
    results[key] = { scrollHeight: 0, nodes: [] };
  } finally {
    await ctx.close();
  }
}

await browser.close();

const live = results.live ?? { nodes: [] };
const local = results.local ?? { nodes: [] };
console.log(`live scrollHeight=${live.scrollHeight}   local scrollHeight=${local.scrollHeight}\n`);

// Align on selector text where possible; the first drifting row is the culprit.
const width = 54;
const pad = (s) => String(s).padEnd(width).slice(0, width);
console.log(`${pad('LIVE  selector')} top/h        ${pad('LOCAL selector')} top/h      Δtop`);
console.log('-'.repeat(150));

const max = Math.max(live.nodes.length, local.nodes.length);
for (let i = 0; i < max; i += 1) {
  const a = live.nodes[i];
  const b = local.nodes[i];
  const aText = a ? `${pad('  '.repeat(a.depth) + a.sel)} ${String(a.top).padStart(5)}/${String(a.h).padStart(5)}` : pad('(none)') + '           ';
  const bText = b ? `${pad('  '.repeat(b.depth) + b.sel)} ${String(b.top).padStart(5)}/${String(b.h).padStart(5)}` : pad('(none)') + '           ';
  const drift = a && b ? b.top - a.top : '';
  const mark = a && b && (b.top !== a.top || b.h !== a.h) ? ' <<<' : '';
  console.log(`${aText}   ${bText}  ${String(drift).padStart(5)}${mark}`);
}

#!/usr/bin/env node
/**
 * Throwaway probe (gitignored scrape/ dir).
 *
 * probe-sections.mjs found zero drift, but it only walked to depth 2 — the
 * footer's brand links sit at `footer > div > ul > li > a` (depth 3+), so a
 * drift *inside* the footer was invisible to it. The iphone-se y=9348 composite
 * shows live stacking creditkarma/quickbooks/mailchimp at ~38px pitch with our
 * copy ~51px higher, while total document heights match exactly (10015/10015).
 *
 * So walk deep (depth 7) over the bottom of the page only, and print LIVE and
 * LOCAL as two separate blocks rather than index-aligned pairs: aligning by
 * index can silently pair up different nodes and fake a match.
 */
import { chromium } from 'playwright-core';
import { launch } from '../scripts/lib/chromium.mjs';

const TARGETS = [
  ['live', 'https://www.intuit.com/intuit-intelligence/'],
  ['local', 'http://localhost:3308/'],
];

const VIEWPORT = { width: 375, height: 667 };
/** Only the tail of the page — the footer/prefooter/disclaimer region. */
const FROM_Y = 8600;

/** Runs in the page. Must not close over anything from this module. */
function measure(fromY) {
  const label = (el) => {
    const cls =
      typeof el.className === 'string' && el.className.trim()
        ? '.' + el.className.trim().split(/\s+/).slice(0, 2).join('.')
        : '';
    return `${el.tagName.toLowerCase()}${el.id ? '#' + el.id : ''}${cls}`;
  };

  const nodes = [];
  const walk = (el, depth) => {
    for (const child of el.children) {
      if (!(child instanceof HTMLElement)) continue;
      const style = getComputedStyle(child);
      if (style.display === 'none' || style.position === 'fixed') continue;
      const rect = child.getBoundingClientRect();
      const top = Math.round(rect.top + window.scrollY);
      const height = child.offsetHeight;
      if (height > 2 && top + height >= fromY) {
        nodes.push({
          depth,
          sel: label(child).slice(0, 44),
          top,
          h: height,
          mt: style.marginTop,
          mb: style.marginBottom,
          pt: style.paddingTop,
          gap: style.rowGap,
          dir: style.flexDirection,
          disp: style.display,
          text: (child.childElementCount === 0 ? child.textContent || '' : '')
            .replace(/\s+/g, ' ')
            .trim()
            .slice(0, 22),
        });
      }
      if (depth < 7) walk(child, depth + 1);
    }
  };
  walk(document.body, 0);
  return { scrollHeight: document.documentElement.scrollHeight, nodes };
}

const results = {};
const browser = await launch(chromium, { headless: true });

for (const [key, url] of TARGETS) {
  const ctx = await browser.newContext({
    viewport: VIEWPORT,
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
  });
  const page = await ctx.newPage();
  try {
    await page.goto(url, { waitUntil: 'load', timeout: 90000 });
    await page.waitForTimeout(3500);
    await page.evaluate(async () => {
      const step = window.innerHeight;
      for (let y = 0; y < document.documentElement.scrollHeight; y += step) {
        window.scrollTo(0, y);
        await new Promise((r) => setTimeout(r, 60));
      }
      window.scrollTo(0, 0);
    });
    await page.waitForTimeout(1200);
    results[key] = await page.evaluate(measure, FROM_Y);
  } catch (err) {
    console.log(`${key} FAILED: ${err.message}`);
    results[key] = { scrollHeight: 0, nodes: [] };
  } finally {
    await ctx.close();
  }
}

await browser.close();

for (const [key, data] of Object.entries(results)) {
  console.log(
    `\n=================== ${key.toUpperCase()}  scrollHeight=${data.scrollHeight}  ` +
      `nodes=${data.nodes.length} (from y=${FROM_Y}) ===================`,
  );
  for (const n of data.nodes) {
    console.log(
      `${'  '.repeat(n.depth)}${n.sel.padEnd(46 - n.depth * 2)} ` +
        `top=${String(n.top).padStart(5)} h=${String(n.h).padStart(4)} ` +
        `disp=${n.disp} dir=${n.dir} gap=${n.gap} mt=${n.mt} mb=${n.mb} pt=${n.pt}` +
        (n.text ? `  "${n.text}"` : ''),
    );
  }
}
